            'note' => 'Les tickets fusionnés ne sont jamais supprimés. Quelle que soit l\'option choisie, une ancienne référence reste toujours consultable et indique où elle a été redirigée &mdash; et un client qui répond à un e-mail à ce sujet vous joint quand même.',
