        'intros' => [
            'custom_fields' => 'Définissez les détails supplémentaires dont un genre de ticket a besoin - une date de début et un nom d\'utilisateur pour un nouvel arrivant, par exemple - et choisissez sur quels types de ticket figure chacun. Chaque champ décide lui-même s\'il doit être renseigné à l\'enregistrement du ticket, à sa fermeture, ou les deux, et si le demandeur est interrogé sur le portail.',
            'checklists' => 'Une liste de contrôle peut marquer des étapes comme obligatoires. Cela décide ce qui se passe si quelqu\'un ferme un ticket avant que ces étapes ne soient cochées.',
            'mandatory_fields' => 'Choisissez quels champs du ticket doivent être renseignés avant sa fermeture, et ce qui se passe si quelqu\'un le ferme alors que l\'un d\'eux est vide. La règle s\'applique partout où un ticket peut être fermé : l\'écran du ticket, les actions groupées, l\'API REST et les workflows.',
            'departments' => 'Les départements regroupent et acheminent les tickets vers le bon secteur de votre organisation — créez ceux que votre service desk utilise pour catégoriser et attribuer le travail.',
            'teams' => 'Les équipes déterminent à quels départements les analystes ont accès. Attribuez des départements aux équipes, puis attribuez des analystes aux équipes pour contrôler leur accès.',
            'ticket_types' => 'Les types de ticket classifient la nature d\'une demande (par exemple Incident, Demande de service) — définissez les types que les analystes peuvent attribuer à un ticket.',
            'ticket_origins' => 'Les origines de ticket indiquent comment un ticket est arrivé (par exemple E-mail, Téléphone, Portail) — définissez les origines parmi lesquelles les analystes peuvent choisir.',
            'mailboxes' => 'Les boîtes aux lettres connectent FreeITSM à des comptes de messagerie afin que les messages entrants deviennent des tickets et que les réponses repartent — ajoutez et authentifiez celles que votre service desk surveille.',
            'privacy' => 'Un ticket ne contient pas seulement votre conversation avec la personne qui l\'a créé. Transférer un message à un fournisseur, ou mettre un collègue en copie, place ce message sur le même ticket — et sa réponse y arrive aussi. Ce paramètre décide de ce que le demandeur voit de tout cela dans le portail libre-service.',
            'indexing' => 'Le texte contenu dans les pièces jointes est lu afin de pouvoir être recherché. Les fichiers Word, Excel, PowerPoint et texte brut sont lus par FreeITSM lui-même, dès leur arrivée. Les PDF, les anciens fichiers Office et les documents numérisés nécessitent un service de lecture de documents distinct — configurez-le dans <strong>Système &rarr; Intégrations &rarr; Apache Tika</strong> — et comme ceux-ci prennent bien plus de temps, ils sont lus en arrière-plan. Ces deux interrupteurs décident du moment où ce travail en arrière-plan a lieu.',
            'merge_behaviour' => 'Lorsque deux tickets s\'avèrent être la même chose, un analyste peut les fusionner. Ces paramètres décident de l\'effet sur les références de ticket détenues par vos demandeurs, et de ce qu\'il advient des conversations. Ils s\'appliquent à tout le monde — une fusion change ce que voit le client, donc deux analystes sur la même boîte aux lettres ne doivent pas pouvoir être en désaccord à ce sujet.',
            'reply_templates' => 'Des réponses prédéfinies que vos analystes peuvent insérer dans une réponse au lieu de les retaper. Ce sont les modèles partagés visibles par toute l\'équipe — les modèles privés propres à un analyste sont enregistrés depuis la fenêtre de réponse et ne figurent pas ici.',
            'rota_shifts' => 'Les vacations sont les modèles d\'horaires de travail (par exemple Matin, Soir, Astreinte) attribués aux analystes sur le planning du personnel — définissez-les ici avant de construire le planning.',
            'analysts' => 'Les analystes sont les membres du personnel qui se connectent et traitent les tickets — ajoutez-les, réinitialisez leurs mots de passe, et attribuez-les à des équipes pour contrôler leur accès.',
            'general' => 'Les paramètres généraux déterminent le comportement des tickets - réouverture, mise en veille, et durée d\'affichage des messages et des fils.',
            'statuses' => 'États du workflow dans lesquels un ticket peut se trouver. Les statuts marqués <em>Fermé</em> comptent comme terminaux — utilisés par les rapports, les compteurs Watchtower et la date/heure de fermeture définie automatiquement lors de l\'attribution. Un seul statut est celui par défaut pour les nouveaux tickets.',
            'priorities' => 'Niveaux de priorité affichés sur les tickets. Une seule priorité est celle par défaut pour les nouveaux tickets.',
            'rota_locations' => 'L\'endroit où chaque analyste travaille un jour donné — utilisé par le planning du personnel et affiché sous forme de badge coloré sur chaque entrée. Un seul lieu est celui par défaut pour les nouvelles entrées du planning.',
            'email_templates' => 'Réponses automatiques par e-mail déclenchées par des événements de ticket. Seul le premier modèle actif par événement est utilisé.',
        ],
        'messaging' => [
            'channels_heading' => 'Canaux de messagerie',
            'channels_intro' => 'Permettez aux clients de discuter avec un analyste via WhatsApp — chaque message devient un ticket, comme pour l\'e-mail. Ajoutez un canal ci-dessous, puis collez son <strong>URL de webhook</strong> chez votre fournisseur (Twilio ou Meta) pour que les messages entrants atteignent cette installation.',
            'base_url_label' => '<strong>URL de base publique</strong>',
            'base_url_placeholder' => 'https://votre-domaine.com  (ou votre adresse ngrok pendant les tests)',
            'base_url_help' => 'L\'adresse que les fournisseurs utilisent pour atteindre cette installation. Définissez-la et les URL de webhook ci-dessous deviennent prêtes à copier-coller. Laissez vide pour utiliser l\'adresse depuis laquelle vous naviguez. Vous testez en local ? Exécutez <code>ngrok http 80</code> et collez l\'adresse <code>https://…ngrok-free.dev</code> qu\'il affiche.',
            'templates_heading' => 'Modèles de message',
            'templates_intro' => 'Les modèles préapprouvés permettent à un analyste de répondre <strong>après la fermeture de la fenêtre de 24 heures</strong>. WhatsApp n\'autorise le texte libre que dans les 24 heures suivant le dernier message du client ; au-delà, seul un modèle approuvé par Meta/Twilio peut être envoyé. Créez &amp; approuvez le modèle chez votre fournisseur, puis ajoutez sa définition ici (avec les espaces réservés <code>{{1}}</code>, <code>{{2}}</code>) afin que les analystes puissent le choisir et le compléter.',
