        'sla' => [
            'heading' => 'Accords de niveau de service',
            'intro' => 'Des SLA tenant compte des heures ouvrées, avec des objectifs de réponse et de résolution par priorité. Le chronomètre s\'arrête sur les statuts marqués « Suspend le SLA » dans l\'<a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">onglet Statuts</a>. Voir les <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">notes de conception</a>.',
            'global_heading' => 'Paramètres globaux',
            'enforce_from' => 'Appliquer les SLA à partir de',
            'enforce_from_help' => 'Laissez vide pour <strong>désactiver complètement l\'application des SLA</strong>. Définissez une date et une heure : seuls les tickets créés à partir de ce moment seront évalués &mdash; utile pour exempter les tickets existants lors de la première activation des SLA.',
