            'save_global' => 'Enregistrer les paramètres globaux',
            'targets_heading' => 'Objectifs SLA par priorité',
            'targets_intro' => 'Délais de réponse et de résolution pour chaque priorité de ticket. Les durées sont en minutes (60 = 1 heure, 240 = 4 heures, 1440 = 1 jour). Le calendrier détermine les heures ouvrées utilisées par le chronomètre. Laissez vide pour ignorer cet objectif.',
            'col_priority' => 'Priorité',
            'col_response_mins' => 'Réponse (min)',
            'col_resolution_mins' => 'Résolution (min)',
            'col_calendar' => 'Calendrier',
            'col_save' => 'Enregistrer',
            'calendars_heading' => 'Calendriers professionnels',
            'calendars_intro' => 'Définissez les heures de travail, les fuseaux horaires et les listes de jours fériés. Les calendriers sont référencés par les objectifs SLA (ci-dessus) et par chaque priorité. Un calendrier est défini par défaut pour les nouvelles priorités.',
            'col_name' => 'Nom',
            'col_timezone' => 'Fuseau horaire',
            'col_hours' => 'Heures',
            'col_holidays' => 'Jours fériés',
            'col_default' => 'Par défaut',
            'default_badge' => 'Par défaut',
            'no_active_priorities' => 'Aucune priorité active - ajoutez-en dans l\'onglet Priorités.',
            'no_calendars' => 'Aucun calendrier défini pour l\'instant. Ajoutez-en un ci-dessus.',
            'col_actions' => 'Actions',
            'notifs_heading' => 'Notifications de dépassement',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Fonctionnement des règles de notification</strong>Chaque règle comporte quatre éléments : une <strong>portée</strong>, un <strong>déclencheur</strong>, une <strong>cible</strong>, et une liste de <strong>destinataires</strong>.<br><br>La <strong>portée</strong> peut être soit <em>Par défaut</em> (la règle s\'applique aux tickets de tous les départements), soit un <em>département spécifique</em> (la règle s\'applique uniquement aux tickets de ce département).<br>Lors de l\'évaluation d\'un ticket, le système cherche d\'abord une règle correspondant à son département &mdash; si elle existe, cette règle l\'emporte et la règle par défaut est ignorée. S\'il n\'y a pas de règle spécifique au département, la règle par défaut est utilisée. Vous pouvez ainsi définir des règles par défaut sensées qui couvrent tous les départements, puis prévoir des exceptions là où une équipe a des besoins d\'escalade différents.<br><br>Le <strong>déclencheur</strong> est soit <em>Avertissement</em> (le ticket a franchi le seuil d\'avertissement &mdash; dépassement potentiel à venir), soit <em>Dépassement</em> (le ticket a maintenant dépassé son objectif SLA &mdash; dépassement réel). Chacun est une règle distincte, ce qui permet de notifier des personnes différentes pour les avertissements et les dépassements.<br><br>La <strong>cible</strong> indique quel chronomètre SLA surveiller &mdash; <em>Réponse</em>, <em>Résolution</em>, ou <em>Les deux</em>.<br><br>Les <strong>destinataires</strong> peuvent être n\'importe quelle combinaison de : l\'assigné actuel du ticket, tous les analystes des équipes du département du ticket, un analyste nommé, et/ou une liste d\'adresses e-mail libres (utile pour les boîtes partagées ou les passerelles e-mail Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Aucune règle = aucun e-mail.</strong> Même si un ticket dépasse son SLA, rien ne se déclenche tant que vous n\'avez pas ajouté au moins une règle (commencez par une paire Avertissement + Dépassement de portée Par défaut pour couvrir l\'ensemble).',
            'notifs_dedup' => 'Chaque ticket déclenche au maximum un e-mail par cible et par déclencheur &mdash; le worker cron suit ce qui a déjà été envoyé pour éviter les doublons.',
            'col_scope' => 'Portée',
            'col_trigger' => 'Déclencheur',
            'col_target' => 'Cible',
            'col_recipients' => 'Destinataires',
            'col_active' => 'Actif',
            'notifs_cron_note' => 'Le worker cron qui envoie ces e-mails se trouve dans <code>cron/sla_breach_check.php</code>. Voir <code>docs/sla-cron-setup.md</code> pour la configuration du Planificateur de tâches Windows et de cron sous Linux.',
            'cron_heading' => 'Activité cron',
            'cron_refresh' => 'Actualiser',
            'cron_intro' => 'Les <span id="slaCronRunsLimit">20</span> dernières exécutions du cron de vérification des dépassements (CLI et HTTP). Inclut les requêtes rejetées (limitation de débit, échec d\'authentification) afin que la même source de vérité serve aussi aux contrôles de limitation de débit et aux audits de sécurité. Purgé automatiquement après <strong><span id="slaCronRetentionDays">30</span> jours</strong> ; l\'intervalle minimum entre deux exécutions réussies est de <strong><span id="slaCronMinInterval">30</span>s</strong> (les deux sont configurables dans <code>system_settings</code>).',
            'col_when' => 'Quand',
