        'rota_weekends' => 'Inclure les week-ends dans le planning',
        'numbering' => [
            'heading' => 'Numérotation des tickets',
            'intro' => 'Chaque ticket reçoit une référence. C\'est ce que l\'on dicte au téléphone, que l\'on note sur un formulaire et que l\'on recherche six mois plus tard : elle mérite donc d\'être quelque chose que l\'on peut prononcer. Vous choisissez sa forme ici.',
            'style' => 'Comment les numéros sont générés',
            'style_sequential' => 'Comptage croissant',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002, etc. Facile à dire, facile à reconnaître, et l\'ordre indique lequel est arrivé en premier.',
            'style_random' => 'Aléatoire',
            'style_random_help' => 'Trois lettres et huit chiffres, comme CKQ-418-73926. C\'est ce que FreeITSM a toujours fait. Personne ne peut deviner combien de tickets vous avez, mais personne ne peut non plus en dicter un à voix haute.',
            'format' => 'À quoi ressemble un numéro',
            'format_help' => 'Placez <code>{######}</code> à l\'endroit où les chiffres doivent apparaître &mdash; un dièse par chiffre. Tout le reste est conservé tel quel. Vous pouvez aussi utiliser <code>{YYYY}</code> ou <code>{YY}</code> pour l\'année, <code>{MM}</code> et <code>{DD}</code>, et <code>{TYPE}</code> ou <code>{COMPANY}</code> pour un code court tiré du type de ticket ou de l\'entreprise. Par exemple <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'Les prochains ressembleraient à',
            'start' => 'Commencer le comptage à partir de',
            'start_help' => 'Utile si vous migrez depuis un autre système et souhaitez reprendre là où il s\'est arrêté.',
            'scope' => 'Compter séparément par',
            'scope_global' => 'Une seule séquence pour tout',
            'scope_per_type' => 'Chaque type de ticket',
            'scope_per_company' => 'Chaque entreprise',
            'scope_help' => 'Compter par type de ticket donne aux incidents et aux demandes leurs propres suites de numéros, ce qui est la méthode de la plupart des grands service desks. Si vous comptez séparément, le format doit indiquer lequel est lequel — insérez-y {TYPE} ou {COMPANY}, sinon chaque groupe produirait les mêmes numéros.',
            'reset' => 'Recommencer',
            'reset_never' => 'Jamais — continuer à compter',
            'reset_yearly' => 'Chaque année',
            'reset_monthly' => 'Chaque mois',
            'reset_help' => 'Utile uniquement si l\'année ou le mois fait partie du numéro, sinon vous obtiendrez des doublons. À combiner avec quelque chose comme <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Rien de ce qui est déjà numéroté ne change.</strong> Les tickets existants conservent leur référence actuelle, et toute référence déjà émise par FreeITSM continue de fonctionner &mdash; y compris dans les réponses aux anciens e-mails. Si vous souhaitez aussi renuméroter les tickets existants, un outil est prévu à cet effet ci-dessous. <strong>Vous ne manquerez pas de chiffres :</strong> la largeur choisie est un minimum, donc le ticket 1 000 001 gagne simplement un chiffre de plus au lieu de casser.',
            'saved' => 'Numérotation des tickets enregistrée.',
            'renumber_heading' => 'Renuméroter les tickets existants',
            'renumber_intro' => 'Réécrit la référence de chaque ticket existant selon le schéma ci-dessus, du plus ancien au plus récent. Surtout utile juste après une migration depuis un autre système, quand vous voulez que tout soit cohérent.',
            'renumber_safety' => '<strong>Les anciennes références continuent de fonctionner.</strong> Chaque numéro qu\'un ticket a déjà eu est mémorisé, si bien qu\'une réponse à un e-mail citant l\'ancien numéro atterrit toujours sur le bon ticket &mdash; exactement comme lors de la fusion de tickets. Un numéro retiré n\'est non plus jamais réattribué à un autre ticket. Ceci ne peut toutefois pas être annulé, alors regardez d\'abord l\'aperçu.',
            'renumber_preview' => 'Aperçu',
            'renumber_go' => 'Renuméroter',
            'renumber_preview_first' => 'Aperçu d\'abord — le bouton s\'active une fois que vous avez vu ce qu\'il ferait.',
            'renumber_preview_heading' => 'Aperçu uniquement &mdash; rien n\'a été modifié.',
            'renumber_done_heading' => 'Tickets renumérotés.',
            'renumber_summary' => '{changing} ticket(s) sur {total} seraient renumérotés. {skipped} correspondent déjà.',
            'renumber_next_after' => 'Le prochain nouveau ticket serait {number}.',
            'renumber_confirm_title' => 'Renuméroter tous les tickets ?',
            'renumber_confirm' => 'Ceci réécrit la référence de chaque ticket existant.

Les anciennes références continuent de fonctionner, donc les réponses aux anciens e-mails trouveront toujours le bon ticket. Mais les numéros que les gens ont notés, mis sur des formulaires et enregistrés dans leurs propres tableurs ne seront plus ceux affichés dans FreeITSM.

Ceci ne peut pas être annulé. Continuer ?',
        ],
        'general' => [
            'system_name' => 'Nom du système',
            'system_name_moved' => 'Le nom du système - la première partie du titre de chaque page - se définit dans {link}, car il s\'applique à tous les modules.',
            'system_name_moved_link' => 'Système -> Image de marque',
            'system_name_placeholder' => 'par ex. Service Desk Ticketing System',
            'system_name_help' => 'Affiché au début du titre de chaque page - le nom dans l\'onglet du navigateur et dans les favoris. Vide signifie « Service Desk ».',
            'reopen_label' => 'Réouverture',
            'reopen_toggle' => 'Rouvrir un ticket fermé quand le demandeur répond',
            'snooze_hour_label' => 'Début de la journée de travail',
            'snooze_hour_help' => 'L\'heure à laquelle un ticket reporté à « Demain » ou « La semaine prochaine » revient. Lu dans le fuseau horaire de chaque analyste, afin qu\'un service réparti sur plusieurs fuseaux ait chacun son propre matin.',
            'collapse_heading' => 'Messages longs',
            'collapse_desc' => 'Les longs e-mails noient ce que vous êtes venu lire en ouvrant le ticket. Les messages dépassant la limite ci-dessous sont raccourcis avec un lien Afficher plus. Rien n\'est supprimé — le message complet reste toujours accessible en un clic.',
            'collapse_enabled_label' => 'Raccourcir les messages longs',
            'collapse_lines_label' => 'Raccourcir les messages dépassant environ',
            'collapse_lines_help' => 'lignes. Un message dépassant à peine la limite reste tel quel, afin que le lien n\'apparaisse pas pour gagner deux mots.',
            'collapse_newest_label' => 'Toujours afficher le message le plus récent en entier',
            'collapse_newest_help' => 'Le message que vous êtes venu lire n\'est jamais raccourci.',
            'collapse_quoted_label' => 'Raccourcir l\'historique cité',
            'collapse_quoted_help' => 'Une réponse courte suivie d\'une longue chaîne citée reste brève en nombre de lignes mais illisible, c\'est pourquoi l\'historique cité est raccourci séparément.',
            'collapse_remember_label' => 'Se souvenir de ce que j\'ai ouvert',
            'collapse_remember_help' => 'Les messages que vous développez restent développés sur cet appareil, afin que la lecture d\'un fil ne se réinitialise pas à chaque actualisation.',
            'group_older_label' => 'Replier les messages plus anciens',
            'group_older_help' => 'Au-delà du nombre ci-dessous, les messages plus anciens se replient en une seule ligne que vous pouvez ouvrir. Un ticket long est un problème différent d\'un message long.',
            'group_show_label' => 'Garder ce nombre de messages récents ouverts',
            'flag_duplicates_label' => 'Signaler les messages déjà arrivés',
            'flag_duplicates_help' => 'Un renvoi, une livraison en double ou un rejet ramenant l\'original est replié avec une note indiquant à quel message il correspond. Rien n\'est supprimé.',
            'team_folders_heading' => 'Dossiers d\'équipe',
            'team_folders_label' => 'Les analystes voient',
            'team_folders_all' => 'Toutes les équipes',
            'team_folders_mine' => 'Uniquement les équipes auxquelles ils appartiennent',
            'team_folders_help' => 'Ne modifie que la liste des dossiers - personne ne perd de vue un ticket. Une équipe détenant des tickets qu\'un analyste peut voir s\'affiche quand même, afin que les dossiers restent cohérents. Les administrateurs voient toujours toutes les équipes.',
            'watch_heading' => 'Suivi des tickets',
            'watch_help' => 'Ce dont les personnes qui suivent un ticket sont informées. Les paramètres de notification de chaque personne s\'appliquent en plus.',
            'watch_inactive_label' => 'Lorsqu\'une personne qui suit un ticket est désactivée',
            'watch_inactive_stop' => 'Cesser de l\'informer - conserver ses suivis au cas où elle reviendrait',
            'watch_inactive_remove' => 'La retirer de tous les tickets qu\'elle suit',
            'watch_inactive_help' => 'Un analyste désactivé n\'est jamais informé de rien. Cesser conserve ses suivis hors de vue et les rétablit si l\'analyste est réactivé ; Retirer les supprime lorsque l\'analyste est désactivé. Le retrait s\'applique à partir de l\'enregistrement de ce paramètre.',
            'watch_event_ticket_reply_received' => 'Le demandeur répond',
            'watch_event_ticket_note_added' => 'Une note est ajoutée',
            'watch_event_ticket_status_changed' => 'Le statut change',
            'watch_event_ticket_priority_changed' => 'La priorité change',
            'watch_event_ticket_assigned' => 'Le ticket est réattribué',
            'watch_event_sla_warning' => 'Il approche de sa cible SLA',
            'watch_event_sla_breached' => 'Il dépasse sa cible SLA',
            'ai_heading' => 'Aides IA à la lecture',
            'ai_desc' => 'Optionnel, et désactivé tant que vous ne l\'activez pas : contrairement au reste de cette page, ces fonctions utilisent votre propre fournisseur IA et ont un coût à chaque utilisation. Le fournisseur, le modèle et la clé API sont configurés une fois pour toutes dans l\'onglet Nettoyage des réponses. Rien de ce qu\'écrit une IA ne remplace jamais le ticket — la conversation reste exactement là où elle est, en entier.',
            'ai_summary_label' => 'Conserver un court résumé IA en haut de chaque ticket',
            'ai_summary_help' => 'Quelques lignes indiquant où en est le ticket, rédigées sur demande et tenues à jour. Il indique toujours quand il a été rédigé, ce qu\'il a lu, et de combien la conversation a avancé depuis. Chaque version est conservée, si bien qu\'un résumé moins bon n\'efface jamais un meilleur résumé.',
            'ai_auto_label' => 'L\'actualiser automatiquement après ce nombre de nouveaux messages',
            'ai_auto_help' => '0 signifie jamais — le bouton Actualiser est alors le seul moyen, et rien n\'est jamais facturé sans qu\'on l\'ait demandé. Une actualisation ne se produit que lorsqu\'un analyste ouvre le ticket, donc une file d\'attente chargée que personne ne consulte ne coûte rien.',
            'ai_max_label' => 'Messages à lire',
            'ai_max_help' => 'Jusqu\'où un résumé remonte dans l\'historique. Un ticket plus long est lu à partir de sa fin la plus récente, et le résumé le précise plutôt que de décrire un début qu\'il n\'a jamais vu.',
            'ai_notes_label' => 'L\'autoriser à lire les notes internes',
            'ai_notes_help' => 'Les notes internes contiennent souvent ce qui a réellement été essayé. Elles restent de toute façon réservées au personnel — le résumé n\'est jamais montré à un demandeur — mais désactivez cette option si les notes de votre service contiennent des informations qui ne doivent pas en sortir.',
            'ai_read_label' => 'Proposer « Lire » sur un ticket',
            'ai_confidential_label' => 'Tickets confidentiels et IA',
            'ai_confidential_block' => 'Ne jamais les envoyer à l\'IA (recommandé)',
            'ai_confidential_allow' => 'Les traiter comme n\'importe quel autre ticket',
            'ai_confidential_help' => 'Couvre toutes les fonctions d\'IA qui lisent un ticket : le résumé, Lire, le nettoyage des réponses, Demander à l\'IA, les résumés de fusion, les rédactions de connaissances, les résumés de canaux, l\'analyse de problème et le bot de la War Room. Un ticket confidentiel n\'est soit pas envoyé, soit - lorsque de nombreux tickets sont lus à la fois - écarté ou affiché uniquement par son numéro.',
            'ai_read_help' => 'Un bouton qui lit tout le ticket et vous en fait un résumé : ce qui s\'est passé, ce qui reste non résolu, et ce qu\'il ferait ensuite. Demandé et lu une seule fois, jamais stocké.',
            'reopen_help' => 'S\'applique partout où un demandeur revient — le portail libre-service, une réponse à votre e-mail de notification, WhatsApp ou le chat web. Le ticket revient à votre premier statut ouvert. Seuls les tickets dans un statut marqué comme fermé sont concernés (définissez lesquels dans Statuts).',
        ],
        'privacy' => [
            'third_party_label' => 'Messages envoyés à quelqu\'un d\'autre que le demandeur',
            'opt_hide' => 'Les masquer au demandeur',
            'opt_hide_help' => 'Le message et ses pièces jointes n\'apparaissent pas du tout dans le portail du demandeur. Recommandé : la plupart des gens supposent que transférer un ticket à un fournisseur reste privé.',
            'opt_no_attachments' => 'Afficher le message, mais pas ses pièces jointes',
            'opt_no_attachments_help' => 'Le demandeur peut voir que vous avez contacté quelqu\'un d\'autre et ce qui a été écrit, mais ne peut pas télécharger les fichiers joints.',
            'opt_show' => 'Tout afficher',
            'opt_show_help' => 'Le demandeur voit l\'intégralité du ticket exactement comme vos analystes, y compris les transferts et les réponses de tiers. C\'était le comportement avant l\'existence de ce paramètre.',
            'always_visible_note' => '<strong>Toujours visible pour le demandeur :</strong> ses propres messages, et toute réponse qui lui est adressée. <strong>Jamais visible :</strong> les notes internes — elles sont masquées du portail quel que soit ce paramètre. Les messages WhatsApp et chat web sont toujours affichés, car ces conversations se déroulent par définition entre le demandeur et votre service.',
            'timezone' => 'Fuseau horaire',
            'timezone_help' => 'Utilisé pour afficher les dates et heures dans tout le système.',
        ],
        'reply_cleanup' => [
            'intro1' => 'Quand un analyste tape une réponse brute dans la fenêtre de rédaction du ticket, le bouton <strong>✨ Nettoyer</strong> la réécrit en e-mail correctement formaté — en ajoutant une formule d\'appel « Bonjour [name], », en corrigeant la grammaire, en appliquant le ton choisi ci-dessous, et en terminant par « Cordialement, ». Il <strong>n\'inventera</strong> jamais de détails techniques ni n\'ajoutera de contenu superflu.',
            'intro2' => 'Cette fonctionnalité utilise sa propre clé API Anthropic (distincte de celles de RFP AI et Knowledge AI), afin que son utilisation apparaisse comme une ligne distincte dans le tableau de bord de facturation Anthropic.',
            'tone' => 'Ton',
            'tone_friendly' => 'Amical (par défaut)',
            'tone_formal' => 'Formel',
            'tone_brief' => 'Bref',
            'tone_help' => 'Appliqué à chaque nettoyage, sauf changement ici.',
            'custom_label' => 'Instructions personnalisées <span style="color: #999; font-weight: normal;">(facultatif)</span>',
            'custom_placeholder' => 'par ex. Terminez toujours par « Merci beaucoup, »&#10;Appelez l\'entreprise « BillCorp »&#10;Utilisez l\'orthographe anglaise britannique partout',
            'custom_help' => 'Ajouté à la fin de l\'invite système affichée à droite. Utilisez ceci pour des ajustements propres à votre organisation (variantes de formule de politesse, nom de l\'entreprise, préférences linguistiques). Les règles de sécurité strictes et le format de sortie restent toutefois prioritaires.',
            'prompt_summary' => 'Voir l\'invite système (lecture seule)',
            'prompt_panel_intro' => 'Voici l\'invite système complète envoyée à Claude à chaque nettoyage. Le nom dans la formule d\'appel varie selon le ticket ; le ton reflète votre sélection à gauche. Vos instructions personnalisées (le cas échéant) sont ajoutées à la fin au moment de l\'exécution — elles ne sont pas affichées ici, modifiez-les dans la zone de texte à gauche.',
        ],
        'csat_tab' => [
            'intro1' => 'Quand un ticket est fermé, envoyer au demandeur un court e-mail d\'enquête lui demandant de noter son expérience de 1&ndash;5. Les réponses sont enregistrées au nom de l\'analyste qui a fermé le ticket, afin de pouvoir suivre les tendances CSAT par analyste, et s\'affichent sous forme de widget sur le tableau de bord.',
            'intro2' => 'L\'e-mail d\'enquête se configure dans <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Modèles d\'e-mail</a> &mdash; créez un modèle avec l\'événement <strong>Enquête CSAT</strong> et intégrez <code>[csat_link]</code> dans le corps pour insérer l\'URL de notation à usage unique.',
            'mode_off' => 'Désactivé',
            'mode_off_help' => 'Aucun e-mail d\'enquête n\'est envoyé.',
            'mode_auto' => 'Automatique à la fermeture',
            'mode_auto_help' => 'Une enquête est envoyée automatiquement quand un ticket passe dans un statut fermé.',
            'mode_manual' => 'Manuel uniquement',
            'mode_manual_help' => 'Les analystes cliquent sur <em>Avis</em> dans la barre d\'outils du ticket lorsqu\'ils souhaitent la demander.',
            'delay_help' => 'Attendre ce nombre de minutes après la fermeture avant l\'envoi. <code>0</code> = immédiat. Utile si vous voulez que l\'utilisateur vérifie que la solution tient réellement avant qu\'on lui demande de la noter.',
            'reminder' => 'Envoyer un rappel si l\'enquête reste sans réponse',
            'reminder_hours' => 'Rappeler après (heures)',
            'reminder_help' => 'Un seul rappel au maximum, par e-mail, avec le même lien - l\'un ou l\'autre e-mail fonctionne donc et une seule évaluation est conservée. Seules les enquêtes envoyées par e-mail sont relancées, qu\'elles soient parties à la fermeture ou depuis le bouton <strong>Commentaires</strong>. Non envoyé si le ticket est rouvert ou dans la corbeille à l\'échéance du rappel. Utilise le modèle d\'e-mail <strong>Rappel CSAT</strong> si vous en avez un, sinon de nouveau le modèle de l\'enquête. Envoyé par la tâche de fond <em>Enquêtes de satisfaction différées et rappels</em>. Activer cette option ne relance pas les personnes pour d\'anciennes enquêtes : seulement celles dont le rappel arrive à échéance à partir de maintenant.',
            'one_per_ticket' => 'Une enquête par ticket',
            'one_per_ticket_help' => 'Si activé, un ticket rouvert puis refermé ne reçoit une nouvelle enquête que si un analyste la déclenche manuellement &mdash; évite de spammer d\'enquêtes un ticket instable.',
            'in_channel' => 'Interroger les clients du chat dans leur chat',
            'in_channel_help' => 'Un client qui a écrit via WhatsApp, Telegram, Slack, Teams ou Mattermost est interrogé dans ce chat &mdash; avec des boutons là où l\'application en propose, « répondez de 1 à 5 » là où elle n\'en propose pas &mdash; plutôt que par e-mail. WhatsApp uniquement tant que sa fenêtre de 24 heures est ouverte ; sinon, et si un message de chat échoue, l\'enquête par e-mail est utilisée.',
            'scale_stars' => 'Étoiles',
            'scale_emojis' => 'Émojis',
            'scale_help' => 'Les deux options enregistrent le même nombre de 1&ndash;5, donc les tableaux de bord et les moyennes fonctionnent de la même façon dans les deux cas &mdash; seul l\'aspect de la page d\'enquête elle-même change.',
