    'help' => [
        'case' => [
            'nav' => 'Rapports de dossier',
            'heading' => 'Rapports de dossier',
            'intro' => 'Lorsqu\'un relecteur ou un auditeur demande comment un dossier a été traité, <strong>Exporter</strong> réunit le ticket, sa conversation et les tâches qui ont fait le travail en un seul document imprimable - personne n\'a donc à le recopier à la main.',
            'step1' => '<strong>Ouvrez le ticket</strong> et choisissez <strong>Exporter</strong> dans sa barre d\'outils (sous <strong>Plus</strong> lorsque le volet de lecture est étroit). Le rapport s\'ouvre dans un nouvel onglet. Pour une tâche sans ticket, utilisez plutôt le bouton document en haut de la fenêtre de la tâche.',
            'step2' => '<strong>Cochez ce qu\'il faut inclure</strong> dans le panneau de gauche. Le rapport se redessine au fil de vos choix, et rien n\'est enregistré pendant que vous choisissez.',
            'step3' => '<strong>Choisissez la mise en page</strong> : une page de couverture, une page de sommaire, chaque section sur une nouvelle page, et un en-tête avec numéros de page.',
            'step4' => '<strong>Imprimez</strong>, puis choisissez <em>Enregistrer au format PDF</em> dans la boîte de dialogue d\'impression. Décochez les <em>En-têtes et pieds de page</em> du navigateur - le rapport imprime les siens.',
            'contents' => '<strong>Ce qui est inclus :</strong> une vue d\'ensemble du ticket (avec ses champs personnalisés, actifs liés, éléments de configuration et tickets associés) ; chaque message, du plus ancien au plus récent ; les notes ; les listes de contrôle du ticket ; chaque tâche liée avec ses sous-tâches, résultats de listes de contrôle et notes d\'exception, réponses aux formulaires, procédures suivies, suivis et commentaires ; l\'historique du ticket et de chaque tâche ; et un index des documents et des pièces jointes d\'e-mail, avec l\'empreinte que FreeITSM a enregistrée pour chaque document.',
            'layout' => '<strong>Mise en page :</strong> la page de sommaire liste chaque section et chaque tâche, et chaque entrée est un lien dans le PDF enregistré. L\'en-tête et les numéros de page (<em>Page 3 sur 12</em>) nécessitent un Chrome ou un Edge récent ; les autres navigateurs impriment le rapport sans eux.',
            'who' => '<strong>Qui voit quoi :</strong> le rapport n\'affiche que ce que vous pouviez voir à l\'écran. Les tâches, actifs, éléments de configuration, tickets associés, documents et réponses aux formulaires sont chacun vérifiés avec leur propre règle, et tout ce que vous n\'avez pas le droit de voir est <em>compté</em> - jamais nommé - pour que le lecteur sache que quelque chose a été omis. <strong>Les notes internes sont exclues sauf si vous les cochez</strong>, car un rapport quitte généralement l\'équipe.',
            'recorded' => '<strong>Ce qui est enregistré :</strong> l\'impression ajoute une ligne <em>Rapport de dossier</em> à la piste d\'audit du ticket, indiquant qui l\'a imprimé et quelles sections il couvrait. L\'aperçu et la modification des choix n\'enregistrent rien.',
            'note' => 'Un rapport de dossier est une copie du dossier, pas une rédaction : rien n\'est reformulé ni résumé, les images contenues dans les e-mails ne sont pas reproduites, les fichiers sont listés et non inclus, et seul l\'historique réellement enregistré par FreeITSM apparaît. Une section qui ne peut pas être lue le dit en rouge au lieu de sembler vide.',
        ],
        'workspace' => [
            'nav' => 'Espace de travail et tableau des tickets',
            'heading' => 'L\'espace de travail et le tableau des tickets',
            'intro' => 'Deux autres façons de traiter les tickets, toutes deux facultatives. L\'<strong>espace de travail</strong> présente un ticket pour le traiter plutôt que pour le lire. Le <strong>tableau des tickets</strong> affiche la liste des tickets sous forme de tableau que vous pouvez filtrer, trier et enregistrer.',
            'ws_title' => 'L\'espace de travail',
            'ws_what' => 'Dans l\'espace de travail, les propriétés du ticket se trouvent dans une colonne à gauche, et sa <strong>Conversation</strong>, son <strong>Travail</strong> (listes de contrôle, formulaires et tâches liées), ses <strong>Liens</strong>, son <strong>Temps et SLA</strong> et son <strong>Historique</strong> sont des onglets à côté. La barre d\'outils et tous les contrôles sont les mêmes que ceux du volet de lecture - seul leur emplacement change. La <strong>liste de contrôle</strong> d\'un ticket énumère chaque étape avec sa case à cocher dans l\'onglet Travail ; <strong>Réduire</strong> n\'affiche que l\'étape suivante (mémorisé dans votre navigateur), et <strong>Détacher</strong> l\'ouvre toujours seule.',
            'ws_admin' => '<strong>Un administrateur l\'active</strong> dans <strong>Tickets &rarr; Paramètres &rarr; Général &rarr; Espace de travail des tickets</strong> : <em>Désactivé</em> (par défaut), <em>Uniquement les tickets transformés en espace de travail</em>, ou <em>Tous les tickets</em>.',
            'ws_make' => '<strong>Transformer un ticket en espace de travail :</strong> avec le réglage intermédiaire, ouvrez le ticket et choisissez <strong>Plus &rarr; Créer un espace de travail</strong> (et <strong>Retour au volet de lecture</strong> pour annuler). Cela appartient au ticket, donc tous ceux qui le traitent le voient de la même façon, et c\'est enregistré dans l\'historique du ticket.',
            'ws_own' => '<strong>Votre propre choix :</strong> une fois activé, <strong>Utiliser l\'espace de travail</strong> dans le menu de filtre de la liste, ou dans <strong>Système &rarr; Préférences</strong>, le désactive pour vous seul. Un ticket transformé en espace de travail affiche alors un petit badge <em>Espace de travail</em>, pour que vous sachiez qu\'un collègue le traite ainsi.',
            'ws_checklist' => '<strong>Les listes de contrôle du ticket énumèrent chaque étape :</strong> dans l\'onglet <strong>Travail</strong>, une liste de contrôle affiche toutes ses étapes avec leurs cases à cocher. <strong>Réduire</strong> la ramène à la seule étape suivante, comme le fait le volet de lecture, et <strong>Développer</strong> ramène le reste - votre navigateur se souvient de votre choix. <strong>Détacher</strong> ouvre toujours la liste de contrôle complète dans une fenêtre.',
            'ws_tasks' => '<strong>Les tâches liées s\'ouvrent sur place :</strong> cliquez sur une tâche dans l\'onglet <strong>Travail</strong> et son propre éditeur s\'ouvre là - listes de contrôle, formulaires, procédures, sous-tâches, commentaires et documents inclus. <strong>Ouvrir séparément</strong> l\'ouvre dans sa propre fenêtre comme avant ; Ctrl-clic fait de même. Vous avez besoin d\'un accès à Tâches pour la modifier.',
            'ws_safe' => '<strong>Rien de ce que vous avez commencé à saisir n\'est perdu :</strong> passer à un autre ticket, ou désactiver l\'espace de travail, avec une réponse, une note ou une modification de tâche non enregistrée vous le demande d\'abord, et attend la fin de tout enregistrement en cours.',
            'tb_title' => 'Le tableau des tickets',
            'tb_what' => 'Choisissez <strong>Tableau</strong> au lieu de <strong>Messages</strong> dans la rangée d\'actions en haut de Tickets (ou dans <strong>Système &rarr; Préférences</strong>). Le dossier dans lequel vous êtes devient le filtre du tableau ; choisissez des colonnes, filtrez-les et triez-les, recherchez, et parcourez la liste par 25, 50 ou 100 tickets à la fois. <strong>Enregistrer la vue</strong> conserve une mise en page pour vous, votre équipe ou tout le monde.',
            'tb_same' => 'Le clic, le Ctrl-clic et le Maj-clic, le clic droit, le glisser vers un dossier et les actions groupées fonctionnent tous comme dans la liste de messages, et le tableau n\'affiche jamais un ticket que la liste n\'afficherait pas.',
            'tb_export' => '<strong>Export CSV :</strong> le bouton CSV exporte <em>chaque</em> ticket correspondant, et pas seulement la page, avec les colonnes affichées. Qui peut l\'utiliser se règle dans <strong>Tickets &rarr; Paramètres &rarr; Général &rarr; Qui peut exporter la liste des tickets</strong> : les administrateurs uniquement (par défaut), toute personne ayant accès à Tickets, ou personne. Le bouton n\'est pas affiché pour les personnes à qui il n\'est pas ouvert.',
            'tb_columns' => '<strong>Pour qui est un ticket :</strong> les colonnes <strong>Demandeur</strong> et <strong>E-mail du demandeur</strong> affichent la personne pour qui le ticket a été créé et son adresse e-mail. Elles sont masquées tant que vous ne les cochez pas dans <strong>Colonnes</strong> ; les deux peuvent être triées, et les deux sont incluses dans l\'export CSV lorsqu\'elles sont affichées.',
        ],
        'page_title' => 'Service Desk - Guide des tickets',
        'sidebar_title' => 'Guide',
        'hero_title' => 'Guide du module Tickets',
        'hero_sub' => 'Enregistrez, suivez et résolvez les demandes d\'assistance informatique depuis une boîte de réception unique organisée en dossiers &mdash; conçu pour les équipes de service desk.',
        'nav' => [
            'overview' => 'Vue d\'ensemble',
            'inbox' => 'La boîte de réception',
            'working_with_tickets' => 'Travailler avec les tickets',
            'working_faster' => 'Travailler plus vite',
            'comments_attachments' => 'Commentaires &amp; pièces jointes',
            'ai_tools' => 'Outils IA',
            'csat' => 'Enquêtes CSAT',
            'user_management' => 'Gestion des utilisateurs',
            'dashboard' => 'Tableau de bord',
            'calendar_rota' => 'Calendrier &amp; planning',
            'settings' => 'Paramètres',
            'tips' => 'Astuces rapides',
            'companies' => 'Entreprises',
        ],
        'overview' => [
            'heading' => 'Vue d\'ensemble',
            'intro' => 'Le module Tickets est le cœur de votre service desk informatique. Il propose une interface familière, dans le style d\'un client de messagerie, pour gérer les demandes d\'assistance, les incidents et les tâches de service. Les tickets arrivent des utilisateurs finaux par e-mail ou sont créés manuellement, et les analystes les traitent à l\'aide de dossiers, de priorités et de minuteurs SLA &mdash; tout ce qu\'il faut pour offrir une assistance informatique réactive.',
            'card_inbox_title' => 'Boîte de réception',
            'card_inbox_body' => 'Une boîte de réception organisée en dossiers, sur le modèle d\'un client de messagerie. Parcourez les dossiers Mes tickets, Non assignés, Tous les ouverts et Fermés. Cliquez sur un ticket pour ouvrir un volet de lecture avec tous les détails, l\'historique et les actions disponibles.',
            'card_dashboard_title' => 'Tableau de bord',
            'card_dashboard_body' => 'Créez un tableau de bord personnalisé avec des widgets Chart.js configurables. Visualisez le volume de tickets, les temps de réponse, la répartition par catégorie et la charge de travail des analystes grâce à des graphiques en barres, en secteurs, en anneau et en courbes.',
            'card_calendar_title' => 'Calendrier',
            'card_calendar_body' => 'Affichez les tickets sur une grille de calendrier selon leur date de création, d\'échéance ou de résolution. Repérez rapidement les tickets en retard et planifiez votre semaine en visualisant l\'ensemble des tickets en un coup d\'œil.',
            'card_rota_title' => 'Planning',
            'card_rota_body' => 'Planifiez les horaires des analystes et les astreintes. Voyez qui est disponible à tout moment, organisez la couverture des week-ends et des jours fériés, et veillez à ce qu\'aucun ticket ne reste sans suivi.',
        ],
        'inbox' => [
            'heading' => 'La boîte de réception',
            'intro' => 'La boîte de réception est l\'espace de travail principal des analystes. Elle utilise une disposition à trois volets &mdash; les dossiers à gauche, la liste des tickets au centre, et un volet de lecture à droite &mdash; pour vous permettre de trier et de répondre sans jamais quitter la page.',
            'p_live' => '<strong>Elle se met à jour toute seule.</strong> Chaque minute, la boîte de réception vérifie vos boîtes aux lettres et cherche tout élément nouveau sur les tickets que vous pouvez voir &mdash; un e-mail collecté en arrière-plan, un message WhatsApp, Telegram, Slack, Teams ou Mattermost, la réponse d\'un collègue &mdash; et lorsque quelque chose est arrivé, la liste et les compteurs de dossiers s\'actualisent d\'eux-mêmes, exactement comme le fait le bouton d\'actualisation. Le ticket que vous lisez et la réponse que vous rédigez ne sont pas touchés.',
            'p_folders' => 'Le panneau des dossiers organise les tickets en groupes logiques. Chaque dossier affiche un nombre de tickets non lus pour repérer immédiatement les nouvelles tâches :',
            'field_my' => '<strong>Mes tickets</strong> &mdash; les tickets qui vous sont assignés. C\'est votre file personnelle, le meilleur point de départ chaque jour.',
            'field_unassigned' => '<strong>Non assignés</strong> &mdash; les tickets arrivés mais sans analyste attitré. Prenez-en un ici pour en devenir responsable.',
            'field_all_open' => '<strong>Tous les ouverts</strong> &mdash; tous les tickets qui ne sont pas encore fermés, quel que soit leur propriétaire. Utile pour les managers et les chefs d\'équipe qui surveillent le volume global.',
            'field_closed' => '<strong>Fermé</strong> &mdash; les tickets résolus. Effectuez vos recherches ici lorsque vous devez retrouver une solution passée ou rouvrir un problème.',
            'field_dept' => '<strong>Dossiers de département</strong> &mdash; les tickets regroupés par département (par exemple IT, RH, Finance). Les départements se configurent dans Paramètres et apparaissent automatiquement en sous-dossiers.',
            'switch_heading' => '<strong>Basculer entre le regroupement par département et par analyste</strong>',
            'switch_body' => 'Un petit sélecteur à deux boutons, en haut du panneau des dossiers, permet de basculer entre deux vues des mêmes données. Le regroupement par <strong>Département</strong> (par défaut) liste les tickets sous chaque département, avec des sous-dossiers de statut à l\'intérieur ; le regroupement par <strong>Analyste</strong> inverse cette logique, chaque dossier de premier niveau représentant la file personnelle d\'un analyste, avec des sous-dossiers de statut à l\'intérieur. Le dossier <strong>Non assignés</strong> s\'adapte au contexte de chaque vue &mdash; en vue Département, il liste les tickets sans département défini ; en vue Analyste, il liste les tickets sans assigné &mdash; afin que vous puissiez toujours voir ce qui reste à prendre en charge. Votre choix est enregistré par analyste, de sorte que chaque membre de l\'équipe retrouve la vue qu\'il préfère d\'une session à l\'autre.',
            'p_actions' => 'Au-dessus de la liste des tickets, vous disposez de quatre boutons d\'action : <strong>Nouveau</strong> pour créer un ticket, <strong>Rechercher</strong> pour trouver des tickets par mot-clé, référence ou demandeur, <strong>Filtrer</strong> pour restreindre ce que vous voyez, et <strong>Actualiser</strong> pour recharger le dossier actuel.',
            'filter_body' => 'Le bouton <strong>Filtrer</strong> (l\'entonnoir) restreint ensemble les dossiers et la liste, quel que soit leur regroupement. <strong>Mes tickets</strong> n\'affiche que les tickets qui vous sont attribués, et <strong>Masquer les fermés</strong> écarte tous les tickets dont le statut est marqué comme fermé. Tant qu\'un filtre est actif, l\'entonnoir porte un point et une étiquette apparaît à côté du titre de la liste, pour que vous sachiez toujours que vous ne voyez pas tout. Lorsque les dossiers sont regroupés par <strong>Analyste</strong>, votre propre dossier se place en haut sous le nom <strong>Mes tickets</strong>. La recherche a son propre interrupteur <strong>Inclure les tickets fermés</strong>, activé par défaut, car on cherche le plus souvent un ancien ticket. Ces deux choix sont enregistrés pour vous seul.',
            'row_name' => 'Chaque ligne affiche la référence du ticket suivie d\'un nom. Par défaut, il s\'agit de <strong>la personne qui a créé le ticket</strong>, et cela ne change pas pendant toute la durée de vie du ticket. Si vous préférez voir l\'auteur du message le plus récent &mdash; qui devient votre propre boîte aux lettres dès que vous avez répondu &mdash; modifiez <strong>Nom à côté du numéro de ticket</strong> dans <strong>Paramètres &rarr; Affichage des lignes</strong>, où vous pouvez aussi masquer le nom pour ne laisser que la référence. Cet onglet est propre à vous : il ne change rien pour les autres.',
            'tip' => 'Cliquez sur un ticket dans la liste pour le charger dans le volet de lecture. Vous pouvez alors mettre à jour les champs, ajouter des commentaires, répondre par e-mail ou joindre des fichiers &mdash; le tout sans quitter la boîte de réception.',
        ],
        'live' => [
            'heading' => 'Mises à jour en direct',
            'body' => 'FreeITSM garde votre écran synchronisé avec tout le monde. Lorsqu\'un collègue modifie un ticket - son statut, sa priorité, son propriétaire ou son équipe, une réponse, une note - votre liste de tickets et le ticket que vous avez ouvert se mettent à jour en 15 secondes environ, sans actualiser. Le tableau des tâches, une tâche ouverte et la cloche fonctionnent de la même façon.',
            'what' => 'La vérification n\'a lieu que lorsque l\'onglet est au premier plan, et la mise à jour se fait dès que vous y revenez. Une modification faite dans un onglet apparaît immédiatement dans vos autres onglets.',
            'safe' => 'Elle ne jette jamais ce que vous êtes en train de faire. Pendant que vous rédigez une réponse ou une note, saisissez dans un champ ou avez un menu ouvert, les nouveaux messages apparaissent quand même dans la conversation, et le reste attend derrière une petite invite <strong>Mis à jour par quelqu\'un d\'autre à l\'instant &middot; Actualiser</strong>.',
            'setting' => '<strong>Préférences &rarr; Mises à jour en direct</strong> permet de choisir toutes les 15 secondes (par défaut), 30 secondes, chaque minute, ou désactivé.',
        ],
        'watch' => [
            'heading' => 'Suivre un ticket',
            'body' => 'Suivez un ticket sans en être responsable - un chef d\'équipe qui garde un œil sur un incident majeur, ou l\'analyste qui l\'a transmis. Les personnes qui suivent un ticket sont informées comme s\'il était le leur, via leurs propres paramètres de notification.',
            'how' => '<strong>Suivre</strong> dans la barre d\'outils du ticket, ou clic droit dessus dans la liste puis <strong>Suivre</strong>. Faites un clic droit sur une sélection pour tous les suivre. Sur un ticket que vous suivez déjà, le bouton de la barre d\'outils et le menu du clic droit indiquent <strong>Ne plus suivre</strong> - une sélection peut être suivie mais pas arrêtée en une seule fois.',
            'others' => 'Le bouton <strong>Suivre</strong> indique qui suit le ticket. Avec un accès en écriture à Tickets, vous pouvez <strong>ajouter un collègue</strong> ou retirer quelqu\'un ; chacun peut se retirer lui-même.',
            'what' => '<strong>Tickets &rarr; Paramètres &rarr; Général &rarr; Suivi des tickets</strong> choisit ce dont les personnes qui suivent sont informées - réponses, notes, statut, priorité, réattribution, avertissements et dépassements SLA - tout, sauf si un administrateur en décoche. Une réattribution parvient à la personne qui suit comme « réattribué », jamais « attribué à vous », et dispose de son propre interrupteur dans les préférences de chacun.',
            'leaver' => 'Un analyste désactivé n\'est jamais informé d\'un ticket qu\'il suit. <strong>Tickets &rarr; Paramètres &rarr; Général &rarr; Lorsqu\'une personne qui suit un ticket est désactivée</strong> décide du sort de ses suivis : <strong>Cesser</strong> (par défaut) les garde hors de vue et les rétablit si l\'analyste est réactivé ; <strong>Retirer</strong> retire l\'analyste de tous les tickets qu\'il suit lorsqu\'il est désactivé.',
            'note' => 'Seules les personnes qui peuvent voir un ticket peuvent le suivre, et si elles cessent de pouvoir le voir, elles cessent d\'en être informées. Personne n\'est informé de sa propre modification. La fusion déplace les personnes qui suivent vers le ticket conservé.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Formulaires sur un ticket',
            'body' => 'Associez un formulaire du module Formulaires à un ticket et remplissez-le là - une demande d\'arrivée d\'un nouveau collaborateur qui nécessite son formulaire d\'équipement, ou un incident de sécurité qui nécessite son rapport. Les réponses sont conservées avec le ticket.',
            'switch' => '<strong>Tickets &rarr; Paramètres &rarr; Listes de contrôle &rarr; Formulaires sur les tickets</strong> l\'active (c\'est désactivé tant que vous ne le faites pas, et le module Formulaires doit aussi être activé). Un bouton <strong>Formulaires</strong> apparaît alors dans la barre d\'outils de chaque ticket, avec le nombre de formulaires soumis. Dans un espace de travail, les formulaires apparaissent aussi dans l\'onglet <strong>Travail</strong>. Faites un clic droit sur un ticket, ou une sélection, et choisissez <strong>Ajouter un formulaire</strong> pour en ajouter un sans l\'ouvrir.',
            'how' => '<strong>Formulaires</strong> ouvre la liste : <strong>Ajouter</strong> choisit un formulaire (toujours sa version la plus récente), <strong>Remplir</strong> l\'ouvre dans une fenêtre, <strong>Enregistrer le brouillon</strong> conserve des réponses inachevées que des collègues peuvent poursuivre, et <strong>Corriger</strong> remplace une soumission tout en conservant l\'ancienne dans Formulaires.',
            'required' => 'Chaque formulaire est <strong>Obligatoire - bloque la fermeture</strong>, <strong>Obligatoire - avertit à la fermeture</strong> ou <strong>Facultatif</strong>. Un formulaire bloquant doit être soumis avant que le ticket puisse atteindre un statut fermé ; un formulaire avec avertissement demande confirmation et enregistre qui a fermé malgré tout.',
            'note' => 'Remplir un formulaire nécessite un accès en écriture à Formulaires et à Tickets. Lire les réponses nécessite l\'accès à Formulaires ou la permission <strong>Lire les réponses aux formulaires des tickets que vous pouvez voir</strong> (un paramètre de rôle) ; les autres voient qui l\'a soumis et quand, mais pas ce qui a été dit. Une soumission dont un ticket dépend ne peut pas être supprimée depuis Formulaires. Les réponses apparaissent dans le rapport de dossier du ticket et dans l\'API REST.',
        ],
        'faster' => [
            'heading' => 'Travailler plus vite',
            'intro' => 'Quatre choses qui transforment une matinée chargée en une matinée maîtrisable : les réponses enregistrées, l\'action sur plusieurs tickets à la fois, et le classement des conversations là où elles doivent aller.',
            'templates_heading' => 'Réponses prédéfinies',
            'templates_body' => 'Vous envoyez sans cesse les mêmes quelques réponses. Rédigez-en une une fois, puis cliquez sur <strong>Modèles</strong> en bas à gauche de la fenêtre de réponse pour l\'insérer à l\'emplacement du curseur &mdash; elle s\'ajoute à ce que vous avez déjà saisi au lieu de le remplacer. Les modèles sont en texte enrichi et prennent en charge les mêmes espaces réservés <code>[merge_code]</code> que les e-mails automatiques, de sorte que <code>[requester_first_name]</code> devient le vrai prénom au moment de l\'insertion.',
            'templates_team' => '<strong>Modèles d\'équipe</strong> &mdash; partagés avec tout le monde, configurés dans Paramètres &rarr; Modèles de réponse.',
            'templates_mine' => '<strong>Les vôtres</strong> &mdash; enregistrez un brouillon avec <em>Enregistrer le brouillon comme modèle</em>. Privés, sans autorisation nécessaire.',
            'templates_tip' => 'Nommez un modèle d\'après la situation (« Imprimante hors service &mdash; premières étapes »), pas d\'après son contenu. C\'est ce que vous chercherez du regard à 9h.',
            'select_heading' => 'Sélectionner plusieurs tickets',
            'select_body' => 'La liste des tickets fonctionne comme Outlook ou l\'Explorateur de fichiers. Pas de cases à cocher.',
            'key_click' => 'Cliquer',
            'key_click_d' => 'sélectionner un ticket et l\'ouvrir',
            'key_ctrl' => 'Ctrl+clic',
            'key_ctrl_d' => 'ajouter ou retirer un ticket, sans toucher aux autres',
            'key_shift' => 'Maj+clic',
            'key_shift_d' => 'sélectionner tout un bloc depuis votre dernier clic',
            'key_kb' => 'Clavier',
            'key_kb_d' => 'les flèches pour se déplacer, Maj+flèches pour étendre la sélection, Ctrl+flèches et Espace pour choisir des tickets dispersés, Ctrl+A pour tout sélectionner, Échap pour effacer la sélection',
            'select_actions' => 'Une fois plusieurs tickets sélectionnés, <strong>faites un clic droit sur l\'un d\'eux</strong> pour définir le statut, la priorité, le département, le type ou l\'assigné pour l\'ensemble &mdash; ou faites glisser toute la sélection sur un dossier. Ce que l\'écran affiche pendant qu\'une sélection multiple est active se choisit dans le menu du compte, sous Préférences.',
            'select_tip' => 'Faire un clic droit sur un ticket qui ne fait <em>pas</em> partie de votre sélection efface celle-ci et ne cible que ce ticket. C\'est voulu &mdash; vous ne pouvez jamais agir par erreur sur une sélection que vous pensiez avoir abandonnée.',
            'merge_heading' => 'Fusionner des doublons',
            'merge_body' => 'Deux personnes ont signalé la même panne ? Sélectionnez les tickets, clic droit, <strong>Fusionner</strong>. Les conversations sont réunies, et si un fournisseur IA est configuré, FreeITSM rédige un court résumé de ce que chacun a demandé et de ce qui a déjà été fait, pour que la personne qui reprend le ticket n\'ait pas à lire quatre fils de discussion.',
            'merge_tip' => 'Rien n\'est jamais supprimé. Le ticket fusionné conserve sa référence, reste consultable dans les recherches, indique où il est passé &mdash; et un client qui répond à un ancien e-mail à son sujet vous joint quand même.',
            'split_heading' => 'Scinder un ticket',
            'split_body' => 'L\'opération inverse. Lorsqu\'une deuxième demande, sans rapport avec la première, apparaît au milieu d\'une conversation, cliquez sur <strong>Scinder</strong> sur ce message (ou faites un clic droit sur l\'en-tête du message). Il est déplacé vers un nouveau ticket, en emportant éventuellement tous les messages plus récents, et le ticket d\'origine conserve un repère indiquant où ils sont passés.',
            'split_tip' => 'Donnez au nouveau ticket un objet approprié. Par défaut, il reprend celui du message déplacé, qui commence généralement par « RE: » suivi de l\'<em>ancien</em> problème.',
            'undo_heading' => 'Vous avez changé d\'avis',
            'undo_body' => 'Les deux opérations peuvent être annulées depuis la bannière du ticket. L\'annulation d\'une <strong>scission</strong> est refusée dès qu\'une réponse a été ajoutée au nouveau ticket, qu\'une note y a été ajoutée ou qu\'un temps y a été enregistré &mdash; le message précise exactement ce qui bloque. L\'annulation d\'une <strong>fusion</strong> restitue au ticket ses messages, ses notes et son temps enregistré, et le rouvre tel qu\'il était, mais les réponses écrites sur l\'autre ticket depuis la fusion y restent.',
        ],
        'working' => [
            'heading' => 'Travailler avec les tickets',
            'intro' => 'Chaque demande d\'assistance suit un cycle de vie : elle est créée, triée, traitée, puis finalement résolue. Le module Tickets vous donne les outils pour gérer efficacement chaque étape, du dépôt initial jusqu\'à la clôture.',
            'creating_heading' => '<strong>Créer un ticket</strong>',
            'step1' => '<strong>Cliquez sur Nouveau</strong> &mdash; ouvre la fenêtre modale de nouveau ticket depuis la barre d\'outils de la boîte de réception. Saisissez le nom et l\'adresse e-mail du demandeur pour qu\'il puisse recevoir les mises à jour.',
            'step2' => '<strong>Définissez le sujet</strong> &mdash; rédigez un résumé clair et concis du problème. Il apparaît dans la liste des tickets et dans les notifications par e-mail envoyées à l\'utilisateur final.',
            'step3' => '<strong>Choisissez le département, le type et la priorité</strong> &mdash; sélectionnez le département approprié, le type de ticket (par ex. Incident, Demande de service) et le niveau de priorité. Ces champs déterminent les délais SLA et les règles de routage.',
            'step4' => '<strong>Ajoutez la description</strong> &mdash; indiquez tous les détails du problème à l\'aide de l\'éditeur de texte enrichi. Incluez les étapes de reproduction, les messages d\'erreur et tout contexte utile pour l\'analyste chargé de la résolution.',
            'step5' => '<strong>Enregistrer</strong> &mdash; le ticket est créé avec un numéro de référence unique et apparaît dans le dossier approprié. Le décompte du SLA démarre immédiatement en fonction de la priorité.',
            'editing_heading' => '<strong>Modifier et gérer les tickets</strong>',
            'editing_body' => 'Une fois le ticket créé, vous pouvez modifier n\'importe quel champ depuis le volet de lecture. Les champs clés sont les suivants :',
            'card_status_title' => 'Statut',
            'card_status_body' => 'Suivez le cycle de vie du ticket : Nouveau, Ouvert, En cours, En attente, Résolu, Fermé',
            'card_priority_title' => 'Priorité',
            'card_priority_body' => 'Définissez l\'urgence et l\'impact : Critique, Élevée, Moyenne, Faible. Chaque niveau a son propre objectif SLA',
            'card_category_title' => 'Catégorie',
            'card_category_body' => 'Classez le type de problème : Matériel, Logiciel, Réseau, Accès, Général. Utile pour les rapports',
            'card_analyst_title' => 'Analyste assigné',
            'card_analyst_body' => 'La personne responsable de la résolution du ticket. Toute réattribution est consignée dans le journal d\'activité',
            'card_enduser_title' => 'Utilisateur final',
            'card_enduser_body' => 'La personne à l\'origine de la demande. Recherchez par nom ou par e-mail pour la relier à une fiche utilisateur existante',
            'card_dept_title' => 'Département',
            'card_dept_body' => 'Acheminez les tickets vers la bonne équipe. Les départements déterminent le regroupement des dossiers et les filtres du tableau de bord',
            'flow_new' => 'Nouveau',
            'flow_in_progress' => 'En cours',
            'flow_resolved' => 'Résolu',
            'flow_closed' => 'Fermé',
            'triage_heading' => '<strong>Triage par glisser-déposer</strong>',
            'triage_body' => 'Il n\'est pas nécessaire d\'ouvrir un ticket pour le trier. Faites glisser n\'importe quelle ligne de la liste des tickets vers un dossier pour mettre à jour plusieurs champs en un seul geste :',
            'triage_dept' => '<strong>Vue par département</strong> &mdash; déposez sur un dossier de département pour réattribuer, déposez sur un sous-dossier de statut au sein d\'un département pour mettre à jour les deux à la fois, déposez sur <strong>Non assigné</strong> pour effacer le département.',
            'triage_analyst' => '<strong>Vue par analyste</strong> &mdash; déposez sur le dossier d\'un analyste pour l\'attribuer comme propriétaire (renseigne à la fois <code>assigned_analyst_id</code> et <code>owner_id</code> afin que le champ Propriétaire du volet de lecture reste synchronisé), déposez sur un sous-dossier de statut pour mettre à jour les deux, déposez sur <strong>Non assigné</strong> pour effacer l\'assigné.',
            'triage_spring' => '<strong>Dossiers à ouverture automatique</strong> &mdash; survolez un dossier réduit pendant un glisser-déposer et il se déplie automatiquement (comme dans Outlook), afin que tout statut imbriqué reste accessible sans avoir à déposer au préalable.',
            'fullscreen_heading' => '<strong>Vue plein écran</strong>',
            'fullscreen_body' => 'Lorsque vous devez vous concentrer sur un seul ticket &mdash; une longue conversation, une modification complexe, la rédaction d\'une réponse détaillée &mdash; passez en vue plein écran. La liste des dossiers et la liste des tickets disparaissent, la conversation occupe toute la largeur disponible, et les propriétés (Département, Type, Statut, Origine, Résolution au premier contact, Formation IT, Propriétaire) se déplacent dans un panneau latéral vertical à droite.',
            'fullscreen_max' => '<strong>Icône d\'agrandissement</strong> &mdash; petite icône à l\'extrémité droite de la ligne du sujet du ticket. Cliquez pour passer en plein écran ; cliquez à nouveau pour revenir à l\'affichage à 3 volets.',
            'fullscreen_dbl' => '<strong>Double-cliquez sur une ligne</strong> &mdash; double-cliquez sur n\'importe quel ticket de la liste pour l\'ouvrir directement en plein écran, un geste « ouvrir vraiment celui-ci » comme dans Outlook.',
            'fullscreen_sticks' => '<strong>Persiste entre les sélections</strong> &mdash; une fois en plein écran, passer au ticket suivant vous y maintient. Un rechargement complet de la page (F5) sans ticket sélectionné revient à l\'affichage par défaut à 3 colonnes, de sorte que vous ne pouvez pas rester bloqué avec la liste des dossiers masquée.',
            'fullscreen_back' => '<strong>Retour</strong> &mdash; la barre au-dessus du ticket affiche sa référence et un bouton <strong>Retour</strong>, qui vous ramène directement à la liste exactement comme vous l\'aviez laissée, avec le clavier de nouveau sur la liste - les flèches se déplacent donc entre les tickets et Entrée ouvre aussitôt le suivant. <strong>Échap</strong> fait de même, une fois fermée toute fenêtre ou tout menu ouvert sur le ticket. Aucun des deux ne désactive le plein écran : le ticket suivant s\'ouvre encore en plein écran (l\'icône de réduction est l\'interrupteur), et en revenant au ticket que vous aviez quitté, vous retrouvez toute réponse commencée.',
            'fullscreen_keys' => '<strong>Les touches font défiler le ticket</strong> &mdash; en plein écran, les flèches, Page précédente / Page suivante et Espace font défiler la conversation, pas la liste de tickets masquée. Dans une fenêtre d\'image ou de PDF, elles font défiler cette fenêtre. Dans la vue normale à trois volets, cliquez dans le ticket et les touches le font défiler aussi ; cliquez sur la liste pour revenir au déplacement entre les tickets.',
            'viewer_heading' => '<strong>Les images et les PDF s\'ouvrent par-dessus le ticket</strong>',
            'viewer_body' => 'Cliquez sur une image ou un PDF joint à une note, ou sur un élément de la liste des <strong>Pièces jointes</strong> du ticket (sa vignette ou sa ligne), et il s\'ouvre dans une fenêtre par-dessus le ticket &mdash; la même visionneuse que le module Fichiers. Le ticket reste exactement où il était en dessous.',
            'viewer_window' => '<strong>Déplacez-la et redimensionnez-la</strong> &mdash; faites glisser la barre de titre pour déplacer la fenêtre et n\'importe quel bord ou coin pour la redimensionner ; double-cliquez sur la barre de titre, ou faites-la glisser en haut de l\'écran, pour remplir l\'écran. L\'image ou le PDF se réajuste quand la fenêtre change de taille, jusqu\'à ce que vous zoomiez vous-même &mdash; <strong>Ajuster</strong> rend la main. Ouvrez-en plusieurs et elles se placent côte à côte.',
            'viewer_close' => '<strong>Fermez-la</strong> &mdash; le &times; dans sa barre de titre, ou <strong>Échap</strong> (qui ferme la fenêtre au premier plan). <strong>Télécharger</strong> enregistre le fichier. Sur un téléphone, le fichier s\'ouvre en plein écran avec un bouton Retour.',
            'viewer_other' => '<strong>Autres fichiers</strong> &mdash; les documents Word, les feuilles de calcul et tout le reste se téléchargent ou s\'ouvrent toujours dans un nouvel onglet, comme avant. Pour ouvrir plutôt l\'image ou le PDF d\'une note dans un nouvel onglet, faites Ctrl-clic dessus.',
            'paste_heading' => '<strong>Coller une capture d\'écran dans une note</strong>',
            'paste_body' => 'Copiez une capture d\'écran, cliquez dans la zone <strong>Ajouter une note</strong> et appuyez sur <strong>Ctrl+V</strong>. L\'image s\'insère à l\'emplacement du curseur, avec votre texte avant et après, et reste à cet endroit une fois la note enregistrée. Cliquez dessus pour l\'ouvrir dans la visionneuse. <strong>Retour arrière</strong> la supprime avant l\'enregistrement.',
            'paste_shared' => '<strong>Les notes partagées partagent leurs images</strong> &mdash; le demandeur les voit sur le portail, à leur place. Sur une note interne, elles sont aussi privées que la note.',
            'paste_save' => '<strong>Rien n\'est conservé tant que vous n\'appuyez pas sur Enregistrer</strong> &mdash; fermez la zone et les images partent avec. Si une image est refusée, la note n\'est pas enregistrée non plus, la raison est affichée, et votre texte reste dans la zone.',
            'paste_text' => '<strong>Le texte reste du texte</strong> &mdash; coller depuis Word, une page web ou Excel insère les mots sans leur mise en forme. Le bouton <strong>Joindre</strong> fonctionne toujours pour tout autre fichier.',
            'rightclick_heading' => '<strong>Clic droit pour les actions rapides</strong>',
            'rightclick_body' => 'Faites un clic droit sur n\'importe quel ticket de la liste pour ouvrir un menu contextuel. Le menu affiche la référence du ticket en haut afin que vous sachiez sur quoi vous agissez, et chaque action s\'applique au ticket sur lequel vous avez cliqué, <em>sans</em> modifier ce qui est actuellement ouvert dans le volet de lecture &mdash; utile lorsque vous lisez le ticket A et devez trier le ticket B sans perdre votre place.',
            'rightclick_status' => '<strong>Définir le statut &rarr;</strong> &mdash; sous-menu déroulant listant tous les statuts actifs avec leur pastille de couleur. Une coche apparaît à côté de la valeur actuelle si vous faites un clic droit sur le ticket que vous avez ouvert. Un choix met immédiatement à jour le ticket, écrit une entrée dans le journal d\'audit, actualise les compteurs de dossiers et synchronise la liste déroulante Statut du volet de lecture le cas échéant.',
            'rightclick_priority' => '<strong>Définir la priorité &rarr;</strong> &mdash; même type de sous-menu, alimenté par la liste des priorités actives, avec la couleur de chacune comme pastille. La première ligne est une option <em>(aucune priorité)</em> permettant d\'effacer l\'attribution (la priorité peut être vide).',
            'rightclick_assign' => '<strong>Attribuer à &rarr;</strong> &mdash; sous-menu listant tous les analystes chargés avec une pastille grise à initiale, ainsi qu\'une ligne <em>(non assigné)</em> en haut pour effacer. Un choix renseigne à la fois <code>assigned_analyst_id</code> ET <code>owner_id</code> afin que le champ Propriétaire du volet de lecture reste synchronisé.',
            'rightclick_cmdb' => '<strong>Lier un objet CMDB&hellip;</strong> &mdash; ouvre un sélecteur avec recherche instantanée. Cliquez sur un résultat pour le lier, puis continuez &mdash; le champ se vide et reprend le focus pour le suivant, et un journal « Récemment lié » dans la fenêtre modale affiche votre liste de confirmations à coche verte.',
            'rightclick_time' => '<strong>Enregistrer du temps&hellip;</strong> &mdash; ouvre une fenêtre modale avec les minutes + un sélecteur de date et heure (par défaut sur « maintenant », mais vous pouvez aussi antidater) + un champ de notes facultatif.',
            'rightclick_more' => '<strong>Associer une liste de contrôle &rarr;</strong>, <strong>Ajouter un formulaire &rarr;</strong> et <strong>Suivre</strong> - associer une liste de contrôle (les meilleures correspondances d\'abord), ajouter un formulaire, ou suivre le ticket sans l\'ouvrir. Sur une sélection, ils agissent sur chaque ticket sélectionné, en ignorant ceux qui ont déjà cette liste de contrôle ou ce formulaire.',
            'rightclick_phone' => '<strong>Sur un téléphone</strong>, appuyez longuement sur un ticket pendant une demi-seconde pour ouvrir le même menu dans un panneau plein écran. Un choix qui offre d\'autres options &mdash; Définir le statut, Définir la priorité, Attribuer à &mdash; glisse vers elles, avec <strong>Retour</strong> pour revenir.',
            'rightclick_tip' => 'Si le ticket sur lequel vous agissez via le menu contextuel est celui actuellement ouvert dans le volet de lecture, la section correspondante (listes déroulantes Statut / Priorité, objets CMDB, temps passé) s\'actualise automatiquement à la fermeture de la fenêtre modale afin que l\'interface reste synchronisée.',
            'time_heading' => '<strong>Enregistrer du temps</strong>',
            'time_body' => 'Le temps passé sur un ticket est consigné dans une section dédiée <strong>Temps passé</strong> du volet de lecture, située entre le panneau des objets CMDB liés et le panneau des notes. L\'en-tête affiche le total cumulé (par exemple « Total 2h 30m »), et chaque entrée ci-dessous indique le temps passé, l\'analyste, la date et les notes éventuelles que vous avez ajoutées.',
            'time_step1' => '<strong>Formulaire intégré</strong> &mdash; saisissez les minutes passées dans le champ numérique, une courte description facultative dans le champ de notes, puis cliquez sur <strong>Ajouter</strong>. La nouvelle entrée apparaît immédiatement en haut de la liste avec votre nom et l\'horodatage actuel.',
            'time_step2' => '<strong>Antidater via le clic droit</strong> &mdash; si vous devez consigner du temps que vous avez oublié d\'enregistrer plus tôt, faites un clic droit sur le ticket dans la liste et choisissez <strong>Enregistrer du temps&hellip;</strong>. La fenêtre modale comprend un sélecteur de date et heure afin de dater l\'entrée avec le moment réel où le travail a été effectué.',
            'time_step3' => '<strong>Supprimer vos propres entrées</strong> &mdash; un petit bouton &times; apparaît à côté des entrées que vous avez enregistrées. Cliquez dessus (et confirmez) pour effectuer une suppression douce &mdash; la ligne reste dans la base de données avec <code>is_active = 0</code> à des fins d\'audit, mais disparaît de la liste. Vous ne pouvez pas supprimer les entrées des autres analystes.',
            'time_tip1' => 'Les durées sont stockées en minutes brutes (45 min, 90 min, etc.) et affichées sous la forme <code>45m</code> ou <code>1h 30m</code> dans l\'interface &mdash; assez précis pour les interventions courtes, sans les soucis d\'arrondi des heures décimales.',
            'time_tip2' => 'Chaque modification de champ est consignée dans le journal d\'activité du ticket. Vous pouvez toujours voir qui a changé quoi et quand, ce qui est essentiel pour la conformité aux audits et la passation entre analystes.',
        ],
        'comments' => [
            'heading' => 'Commentaires &amp; pièces jointes',
            'intro' => 'Le journal d\'activité est au cœur de chaque ticket. Il capture chaque action effectuée &mdash; commentaires, modifications de champs, e-mails envoyés et fichiers joints &mdash; dans une chronologie qui raconte toute l\'histoire d\'une demande d\'assistance.',
            'adding_heading' => '<strong>Ajouter des commentaires</strong>',
            'step1' => '<strong>Ouvrez le ticket</strong> &mdash; cliquez sur n\'importe quel ticket dans la boîte de réception pour charger son volet de lecture. Faites défiler vers le bas pour voir le journal d\'activité complet et la zone de commentaire en bas.',
            'step2' => '<strong>Rédigez votre note</strong> &mdash; utilisez le bouton Ajouter une note pour ouvrir l\'éditeur de commentaire. Les notes sont internes par défaut, visibles uniquement par les analystes du service desk.',
            'step3' => '<strong>Répondre ou transférer par e-mail</strong> &mdash; utilisez les actions Répondre ou Transférer pour envoyer un message à l\'utilisateur final ou à un tiers. L\'e-mail est consigné dans le journal d\'activité avec le contenu du message envoyé.',
            'subject_note' => '<strong>Le sujet</strong> &mdash; Répondre et Transférer affichent le sujet, et vous pouvez le modifier. Quand vous transférez un ticket à un prestataire externe et que sa réponse ajoute son propre numéro au sujet (par exemple <em>#TCK89633 - TR : &hellip;</em>), utilisez <strong>Répondre</strong> ou <strong>Transférer</strong> sur <em>ce</em> message dans la conversation : l\'action part de son sujet, afin que votre suite conserve son numéro et arrive sur son ticket. Chaque message affiche son propre sujet sous l\'expéditeur. La référence du ticket entre crochets est toujours conservée &mdash; si vous la retirez, elle est remise à l\'envoi, afin que les réponses reviennent bien sur ce ticket.',
            'requester_note' => '<strong>Changer le demandeur</strong> &mdash; <strong>Changer le demandeur</strong>, à côté de l\'expéditeur en haut du ticket, rend le ticket à quelqu\'un d\'autre : un collègue qui l\'a saisi en son nom, une erreur à la réception. C\'est consigné dans l\'historique du ticket. Quand l\'ancien demandeur semble être la même personne écrivant depuis une autre adresse, il vous est proposé de la fusionner : ses autres tickets sont déplacés aussi, et son adresse devient l\'une de celles de la nouvelle personne, si bien que son prochain e-mail arrivera là. Une ligne <strong>Demandeur</strong> sous l\'expéditeur s\'affiche chaque fois que le ticket concerne quelqu\'un d\'autre que la personne qui a écrit le message. Le courrier d\'une adresse liée à une personne (Personnes &rarr; sa page &rarr; Adresses e-mail) est le sien, il ne crée donc jamais une seconde personne.',
            'addresses_note' => '<strong>Adresses à la saisie</strong> &mdash; commencez à saisir dans <strong>À</strong> ou <strong>Cc</strong> et FreeITSM suggère des adresses : d\'abord le <strong>service desk</strong> d\'un fournisseur (à définir sur le fournisseur dans Contrats), puis les contacts du fournisseur, les personnes de l\'entreprise du ticket, et les adresses contactées récemment depuis les tickets de cette entreprise. Utilisez les flèches et Entrée, ou cliquez ; choisissez-en autant que vous voulez, ou continuez à saisir les vôtres. Une adresse issue des tickets d\'une entreprise n\'est jamais suggérée sur ceux d\'une autre, et les destinataires d\'un ticket confidentiel ne sont jamais suggérés.',
            'attachments_note' => '<strong>Pièces jointes d\'e-mail</strong> &mdash; dans la liste des pièces jointes, un clic en ouvre une dans une fenêtre au-dessus du ticket quand le type de fichier le permet : images, PDF, documents Word, feuilles de calcul et fichiers CSV, texte, audio et vidéo, avec un bouton de téléchargement. Tout le reste se télécharge. <strong>Enregistrer dans Fichiers</strong> à côté de chacune - et à côté de chaque fichier d\'une note - la copie dans un dossier de Fichiers. Pour mettre sur le ticket un fichier déjà présent dans Fichiers, utilisez <strong>Depuis Fichiers</strong> dans la fenêtre <strong>Ajouter une note</strong> (<strong>Depuis l\'ordinateur</strong> est le bouton voisin) - une fenêtre comme une boîte de dialogue de fichiers s\'ouvre, avec les dossiers à gauche et leurs fichiers à droite - sous forme de lien (ouvert via Fichiers, selon les permissions de son dossier, jamais affiché dans le portail) ou de copie, selon ce que Fichiers &rarr; Paramètres &rarr; Partage autorise.',
            'files_heading' => '<strong>Pièces jointes</strong>',
            'files_body' => 'Joignez des captures d\'écran, des journaux, des documents ou tout autre fichier justificatif directement à un ticket. Les fichiers peuvent être glissés dans la zone de dépôt des pièces jointes ou sélectionnés à l\'aide de l\'explorateur de fichiers. Les pièces jointes sont stockées sur le serveur et liées au journal d\'activité du ticket afin que rien ne soit perdu.',
            'audit_heading' => '<strong>Journalisation d\'audit</strong>',
            'export_heading' => '<strong>Rapports de dossier</strong>',
            'export_body' => 'Pour une revue ou un auditeur, <strong>Exporter</strong> dans la barre d\'outils du ticket transforme le ticket et ses tâches en un seul rapport imprimable - voir <a href="#case-reports">Rapports de dossier</a>.',
            'audit_body' => 'Le journal d\'activité enregistre automatiquement chaque action sans intervention de l\'analyste. Lorsqu\'une priorité passe de Moyenne à Élevée, les anciennes et nouvelles valeurs sont capturées. Lorsqu\'un ticket est réattribué, l\'ancien et le nouvel analyste sont tous deux consignés. Cela crée un historique complet et infalsifiable qui satisfait aux exigences d\'audit ITIL et aide les responsables à comprendre comment les tickets sont traités.',
            'tip' => 'Lorsque vous répondez par e-mail, vous pouvez ajouter des destinataires en Cc et joindre des fichiers dans la même action. Toute la conversation par e-mail est intégrée au journal d\'activité du ticket, ce qui regroupe toutes les communications au même endroit.',
        ],
        'ai' => [
            'heading' => 'Outils IA',
            'intro' => 'Deux fonctionnalités propulsées par Claude s\'intègrent dans le flux de traitement des tickets : <strong>Nettoyage de la réponse</strong> reformule un brouillon en un e-mail correctement mis en forme, et <strong>Demander à l\'IA</strong> recherche dans la base de connaissances en langage naturel à partir du contexte du ticket.',
            'cleanup_heading' => '<strong>Nettoyage de la réponse &mdash; bouton ✨ dans l\'éditeur de réponse</strong>',
            'cleanup_body' => 'Saisissez un brouillon rapide dans une réponse (ou simplement des puces comme *« il faut redémarrer le service d\'impression, faire une capture d\'écran pour eux »*) et cliquez sur le bouton <strong>✨ Nettoyer</strong>. Claude le réécrit sous la forme d\'un e-mail correctement mis en forme &mdash; ajoute une formule d\'appel <em>Bonjour [nom],</em> reprenant le nom du demandeur, corrige la grammaire, applique le ton configuré, et se termine par <em>Cordialement,</em>. Le prompt est verrouillé de façon à ne JAMAIS inventer de détails techniques, fabriquer des excuses, ou étoffer le contenu au-delà de ce que vous avez écrit.',
            'cleanup_streams' => '<strong>Diffusion en direct</strong> &mdash; la réécriture apparaît dans l\'éditeur au fur et à mesure que Claude la génère (pas d\'attente devant un indicateur de chargement).',
            'cleanup_undo' => '<strong>Lien Annuler pendant 30 s</strong> &mdash; si jamais Claude rate la réécriture, un petit lien <em>Annuler</em> apparaît sous l\'éditeur pendant 30 secondes après la fin de la réécriture, pour restaurer le brouillon d\'origine.',
            'cleanup_tone' => '<strong>Par ton</strong> &mdash; trois préréglages de ton configurables sous <strong>Paramètres &rarr; Nettoyage de la réponse</strong> : <em>Amical</em> (par défaut), <em>Formel</em>, <em>Bref</em>. Choisissez celui qui correspond au style de votre équipe.',
            'cleanup_key' => '<strong>Clé API dédiée</strong> &mdash; clé Anthropic distincte de celle des fonctionnalités IA RFP / Connaissances / Workflow, afin que son utilisation apparaisse comme une ligne à part sur le tableau de bord de facturation Anthropic. Se configure sous <strong>Paramètres &rarr; Nettoyage de la réponse</strong>.',
            'cleanup_tip' => 'Le nettoyage est surtout utile pour les réponses courantes du type « j\'ai essayé ceci, merci d\'essayer X ». Pour les messages longs et nuancés, mieux vaut les rédiger vous-même &mdash; l\'IA excelle sur la structure mais ne connaît pas votre environnement spécifique.',
            'ask_heading' => '<strong>Demander à l\'IA &mdash; bouton 🤖 dans la barre d\'outils du ticket</strong>',
            'ask_body' => 'Cliquez sur le bouton <strong>Demander à l\'IA</strong> (🤖) dans la barre d\'outils du ticket pour ouvrir un panneau de discussion coulissant qui connaît le sujet, le corps et le contexte du volet de lecture du ticket ouvert. Posez-lui des questions comme *« avons-nous déjà vu ce cas ? »* ou *« quel est le correctif habituel pour cette erreur ? »* et il effectue une recherche sémantique dans la base de <a href="../knowledge/" style="color:#0078d4;">Connaissances</a> (via Claude + les embeddings OpenAI) et répond avec les articles pertinents, avec des liens directs pour les ouvrir.',
            'ask_context' => '<strong>Sensible au contexte</strong> &mdash; le panneau sait quel ticket vous consultez, vous pouvez donc poser des questions génériques et il détermine lui-même le contexte pertinent.',
            'ask_linked' => '<strong>Articles liés</strong> &mdash; les suggestions sont cliquables et ouvrent l\'article de connaissances correspondant dans un nouvel onglet.',
            'ask_shared' => '<strong>Partagé avec le module Connaissances</strong> &mdash; l\'IA utilise la même clé et le même modèle que la recherche IA du module Connaissances, donc une seule configuration suffit pour les deux. Consultez l\'aide du module Connaissances pour les détails de configuration.',
        ],
        'csat' => [
            'heading' => 'Enquêtes de satisfaction client (CSAT)',
            'intro' => 'Envoyez par e-mail une enquête de satisfaction de 1&ndash;5 au demandeur lorsqu\'un ticket est résolu, enregistrez la réponse sur une page d\'atterrissage sans connexion, et suivez les tendances par analyste sur une page d\'analyse dédiée.',
            'modes_heading' => '<strong>Deux modes de déclenchement &mdash; choisissez-en un</strong>',
            'mode_auto' => '<strong>Automatique à la fermeture</strong> &mdash; l\'enquête est mise en file d\'attente automatiquement lorsqu\'un ticket passe à un statut fermé. L\'analyste n\'a rien à faire &mdash; c\'est la résolution qui déclenche l\'enquête.',
            'mode_manual' => '<strong>Manuel uniquement</strong> &mdash; l\'analyste clique sur le bouton ⭐ <strong>Feedback</strong> dans la barre d\'outils du ticket lorsqu\'il souhaite le demander. Utile si vous préférez décider ticket par ticket s\'il faut solliciter un avis.',
            'starters_note' => '<strong>Les tickets créés par un dossier Arrivants &amp; partants</strong> (une étape de modèle créée sous forme de ticket) ne reçoivent aucune enquête automatique, et leur demandeur aucun e-mail automatique, sauf si le modèle coche <strong>Informer le demandeur par e-mail de ces tickets</strong>. Chaque e-mail non envoyé figure dans le journal d\'envoi de la boîte aux lettres comme ignoré, avec la raison. Le ticket indique dans ses liens de quel dossier il relève.',
            'switch_note' => 'Vous n\'utilisez pas du tout CSAT ? Désactivez-le sous <strong>Système &rarr; Modules &rarr; Disponibilité &rarr; Fonctionnalités des tickets</strong> et il disparaît : plus d\'enquêtes, plus de page CSAT, plus de bouton Demander un avis, et les anciens liens d\'enquête indiquent que les commentaires ne sont plus recueillis. Rien n\'est supprimé.',
            'mode_off' => '<strong>Désactivé</strong> &mdash; fonctionnalité désactivée ; aucun e-mail d\'enquête n\'est envoyé.',
            'modes_choose' => 'Choisissez le mode dans <strong>Tickets &rarr; Paramètres &rarr; CSAT</strong>. Le bouton manuel fonctionne toujours en mode <em>automatique</em> &mdash; les analystes peuvent redemander un avis sur un ticket déjà enquêté si nécessaire.',
            'template_heading' => '<strong>Le modèle d\'e-mail</strong>',
            'template_body' => 'Le contenu de l\'e-mail d\'enquête provient de l\'onglet existant <strong>Modèles d\'e-mail</strong> &mdash; créez un modèle avec l\'événement <strong>Enquête CSAT</strong> (le nouvel événement aux côtés de <em>Ticket attribué</em> / <em>Ticket fermé</em>) et intégrez le code de fusion <code>[csat_link]</code> à l\'endroit où vous voulez que l\'URL de notation apparaisse. Les codes de fusion standards (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) restent disponibles normalement.',
            'template_tip' => 'Si aucun modèle CSAT actif n\'existe, le bouton <em>Feedback</em> refuse avec une erreur claire et le déclenchement automatique est ignoré silencieusement &mdash; vous ne pouvez jamais produire de liens d\'enquête morts.',
            'survey_heading' => '<strong>La page d\'enquête</strong>',
            'survey_body' => 'Le demandeur clique sur le lien dans l\'e-mail et arrive sur une page sans connexion avec un sélecteur de 1&ndash;5 et une zone de commentaire facultative. Deux styles visuels configurables dans <strong>Paramètres &rarr; CSAT</strong> :',
            'survey_stars' => '<strong>Étoiles</strong> &mdash; comportement classique de remplissage progressif au survol. Survoler l\'étoile n°3 remplit les étoiles n°1, n°2 et n°3 en doré. Cliquez pour valider.',
            'survey_emojis' => '<strong>Émojis</strong> &mdash; 5 visages 😡 🙁 😐 🙂 😀 commencent en niveaux de gris à 40 % d\'opacité ; celui survolé ou sélectionné retrouve sa pleine couleur à une échelle de 1,25&times;. Cliquez pour valider.',
            'survey_store' => 'Les deux modes enregistrent le même nombre de 1&ndash;5, de sorte que les tableaux de bord et les moyennes fonctionnent de façon identique quel que soit le style utilisé. L\'URL de l\'enquête est à usage unique &mdash; une fois la réponse envoyée, le même lien refuse toute nouvelle soumission.',
            'chat_heading' => '<strong>Interroger les clients du chat dans leur chat</strong>',
            'chat_body' => 'Quand <strong>Interroger les clients du chat dans leur chat</strong> est coché, un client qui a écrit par WhatsApp, Telegram, Slack, Microsoft Teams ou Mattermost est interrogé dans ce chat plutôt que par e-mail &mdash; cinq boutons sur Telegram, Teams et Mattermost, &ldquo;répondez par un seul chiffre&rdquo; ailleurs. Sa réponse rejoint les mêmes résultats qu\'une enquête envoyée par e-mail.',
            'chat_rules' => 'WhatsApp n\'est sollicité que tant que sa fenêtre de réponse de 24 heures est ouverte ; en dehors, ou si le message de chat ne peut pas être envoyé, l\'enquête par e-mail est utilisée à la place. Un chiffre ne compte comme une note que s\'il suit immédiatement la question &mdash; dans le même chat, dans la semaine, et avant que le client ait écrit autre chose &mdash; de sorte qu\'un &ldquo;3&rdquo; répondant à la question d\'un analyste reste un simple message. Désactivé après une mise à niveau ; activé pour une nouvelle installation.',
            'analytics_heading' => '<strong>La page d\'analyse</strong>',
            'analytics_body' => 'Cliquez sur le bouton de navigation ⭐ <strong>CSAT</strong> (entre Planning et Paramètres) pour ouvrir le tableau de bord d\'analyse à <code>tickets/csat/</code>. Période sélectionnable : 7 / 30 / 90 / 365 jours.',
            'card_kpi_title' => 'Vignettes d\'indicateurs clés',
            'card_kpi_body' => 'Note moyenne (sur 5), nombre de réponses, taux de réponse (répondus ÷ envoyés)',
            'card_dist_title' => 'Répartition des notes',
            'card_dist_body' => 'Graphique à barres des notes de 1 à 5 indiquant les nombres exacts et les pourcentages',
            'card_leader_title' => 'Classement par analyste',
            'card_leader_body' => 'Note moyenne et nombre de réponses par analyste, triés par moyenne décroissante. À utiliser pour les entretiens de développement',
            'card_recent_title' => 'Réponses récentes',
            'card_recent_body' => 'Les notes les plus récentes d\'abord, 25 par page, avec leurs commentaires libres et le client qui les a laissés, reliées au ticket d\'origine',
            'analytics_filters' => 'Affinez la page avec les filtres sous le titre : une plage de dates <strong>De / À</strong> (au lieu des boutons de jours), une tranche de <strong>Note</strong> (Positives 4-5, Neutres 3, Négatives 1-2), un <strong>Analyste</strong> et un <strong>Client</strong>. L\'analyste et le client affinent tous les chiffres de la page ; la tranche de note n\'affine que la liste des réponses, afin que la moyenne garde un sens. Sur un téléphone, les filtres se trouvent derrière le bouton <strong>Filtres</strong> en bas de l\'écran. Une page filtrée peut être mise en favori.',
            'analytics_company' => 'Chaque chiffre suit le <strong>sélecteur d\'entreprise</strong> de l\'en-tête : l\'entreprise sélectionnée, ou toutes les entreprises que vous pouvez voir sous <strong>Toutes les entreprises</strong>.',
            'analytics_tip' => 'L\'attribution par analyste survit à une réattribution du ticket, car l\'identifiant de l\'analyste est enregistré sur la ligne de l\'enquête au moment de l\'envoi, et non recherché en temps réel. Si un ticket change plusieurs fois de mains avant d\'être fermé, c\'est l\'analyste qui l\'a effectivement fermé qui reçoit la note.',
            'one_heading' => '<strong>Une enquête par ticket</strong>',
            'one_body' => 'Si <em>Une enquête par ticket</em> est activé (par défaut), un ticket rouvert puis refermé ne reçoit une nouvelle enquête que si un analyste la déclenche manuellement &mdash; cela évite de spammer d\'enquêtes un ticket instable qui boucle sans cesse. Désactivez cette option si vous voulez qu\'une nouvelle enquête soit envoyée à chaque fermeture.',
        ],
        'users' => [
            'heading' => 'Gestion des utilisateurs',
            'intro' => 'Le bouton de navigation <strong>Utilisateurs</strong> ouvre <code>tickets/users.php</code> &mdash; un annuaire de tous les utilisateurs finaux (les personnes qui créent des tickets, pas les analystes) avec l\'historique des tickets de chacun.',
            'p_intro' => 'Les utilisateurs arrivent dans le système de quatre façons réactives &mdash; auto-inscription sur le portail, e-mail entrant d\'un nouvel expéditeur, la vérification périodique de la boîte aux lettres, ou le moteur de workflow qui en crée un à partir d\'un ticket déclenché. Cela couvre la plupart des cas, mais la page Utilisateurs vous permet aussi de <strong>pré-créer</strong> un utilisateur (par exemple un nouvel arrivant qui va bientôt avoir besoin d\'un accès) et de <strong>modifier</strong> ou <strong>supprimer</strong> des lignes existantes.',
            'add_heading' => '<strong>Ajouter un utilisateur</strong>',
            'add_body' => 'Le bouton <strong>Ajouter</strong> dans l\'en-tête de la liste des utilisateurs ouvre l\'éditeur de personne. C\'est le même éditeur que celui qu\'ouvre <strong>Actifs &rarr; Utilisateurs</strong>, de sorte qu\'une personne est ajoutée et modifiée de la même façon quel que soit l\'écran :',
            'add_email' => '<strong>E-mail</strong> &mdash; facultatif, car les personnes qui se connectent via un annuaire peuvent n\'avoir aucune boîte aux lettres ; elles sont alors retrouvées par leur nom de connexion. Indiquez soit une adresse e-mail, soit un nom affiché. Une adresse doit être unique et ne doit pas appartenir à un analyste.',
            'add_names' => '<strong>Nom affiché / nom préféré</strong> &mdash; facultatif. Le nom préféré est celui utilisé pour saluer l\'utilisateur dans les e-mails (par exemple <em>« Ed »</em> plutôt que <em>« Ed Mozley »</em>).',
            'add_password' => '<strong>Mot de passe</strong> &mdash; facultatif. Le laisser vide crée un compte <em>sans mot de passe</em> &mdash; exactement le même état que celui des utilisateurs créés par ticket entrant. L\'utilisateur peut ensuite s\'approprier le compte via le parcours d\'inscription du portail libre-service en définissant son propre mot de passe.',
            'add_details' => '<strong>Intitulé du poste, département, bureau, téléphone, mobile, matricule et responsable</strong> &mdash; tous facultatifs, et tous décrivant la <em>personne</em> plutôt que la connexion. Utile à renseigner : le <strong>bureau</strong> indique sur quel site se trouve quelqu\'un avant que vous le cherchiez, le <strong>responsable</strong> enregistre la ligne hiérarchique (saisissez une partie du nom pour le trouver), et le <strong>matricule</strong> sert de clé de jointure lorsque vous rapprochez avec un système de paie qui n\'a jamais entendu parler d\'adresse e-mail. Lorsque vous importez depuis un annuaire, tous ces champs arrivent remplis. Un carnet d\'adresses CardDAV remplit tout sauf le matricule et le responsable, qu\'une fiche de contact n\'a nulle part où stocker.',
            'managed_heading' => '<strong>Personnes gérées ailleurs</strong>',
            'source_body' => '<strong>La provenance d\'une personne</strong> est indiquée dans ses détails (<em>Détails provenant de : Contoso AD - annuaire</em>), et le filtre <strong>Source</strong> sous la zone de recherche n\'affiche que les personnes d\'un annuaire ou d\'un carnet d\'adresses donné, ou seulement celles ajoutées dans FreeITSM, avec un nombre à côté de chacune. Il apparaît dès qu\'une personne est liée à une source.',
            'add_book_body' => '<strong>Ajouter au carnet d\'adresses.</strong> Quelqu\'un qui a envoyé un e-mail existe ici mais dans aucun carnet d\'adresses. Si un administrateur a activé <em>Autoriser les analystes à ajouter des personnes à ce carnet d\'adresses</em> (Système &rarr; Authentification, sur le carnet d\'adresses), cette personne obtient un bouton <strong>Ajouter au carnet d\'adresses</strong> à côté de Modifier. Une confirmation est demandée au préalable, montrant ce qui figurera sur la fiche, puis le contact est créé et lié &mdash; la même personne, pas une copie. Cela n\'ajoutera pas quelqu\'un dont l\'adresse e-mail figure déjà dans le carnet (lancez plutôt l\'import), et cela garantit que le prochain import récupérera le nouveau contact, ou retirera la fiche.',
            'managed_body' => 'Lorsqu\'une personne a été importée &mdash; depuis LDAP ou Active Directory, ou depuis un carnet d\'adresses CardDAV &mdash; les champs que possède cette source sont en <strong>lecture seule</strong> et la fenêtre modale les grise. La source d\'origine fait référence, et le prochain import écraserait tout ce qui serait saisi ici, donc l\'enregistrement est refusé d\'emblée plutôt qu\'accepté puis annulé discrètement une heure plus tard. <strong>Les champs concernés</strong> dépendent de la source : un annuaire en possède les sept, tandis qu\'un carnet d\'adresses en possède cinq &mdash; il n\'a nulle part où conserver un matricule ou une ligne hiérarchique, donc ces deux-là restent à votre charge. Et si le carnet d\'adresses a l\'option <em>réécrire les modifications</em> activée, aucun champ n\'est verrouillé : ce que vous saisissez est envoyé à la fiche de contact, il n\'y a donc rien à annuler au prochain import. Tout le reste de la fiche, y compris l\'entreprise et le mot de passe, reste toujours modifiable.',
            'edit_heading' => '<strong>Modifier un utilisateur</strong>',
            'edit_body' => 'Sélectionnez un utilisateur dans la liste, puis cliquez sur <strong>Modifier</strong> dans l\'en-tête de détail. Même éditeur, prérempli. Enregistrer sans mot de passe laisse intact le hachage existant ; en fournir un le réinitialise. Si son responsable est quelqu\'un d\'une entreprise que vous ne pouvez pas voir, la zone Responsable l\'indique et le responsable est conservé tel quel, sauf si vous en choisissez un autre.',
            'signin_body' => '<strong>Se connecte avec</strong> indique à quel fournisseur d\'authentification unique une personne est liée. <strong>Délier</strong>, à côté, après confirmation, supprime ce lien afin que sa prochaine connexion reparte de zéro &mdash; pour quelqu\'un qui est passé à un autre fournisseur, ou qui a été lié au mauvais compte. Cette option n\'est pas proposée pour les personnes gérées par une synchronisation d\'annuaire, qui les lierait simplement de nouveau.',
            'company_body' => '<strong>Entreprise</strong> apparaît lorsque vous en avez plusieurs. Pour une nouvelle personne, la laisser vide déduit l\'entreprise de son adresse e-mail ; pour une personne existante, vide signifie aucune entreprise, et ses tickets vont au triage.',
            'managers_heading' => '<strong>Responsables</strong>',
            'managers_body' => 'Une personne peut devenir <strong>responsable</strong> dans le portail libre-service : elle obtient un onglet <strong>Tickets de l\'équipe</strong> listant les tickets des personnes qu\'elle encadre. C\'est désactivé tant qu\'un administrateur ne l\'active pas sous <strong>Système &rarr; Responsables</strong>, qui décide aussi si les responsables peuvent répondre à ces tickets ou les fermer, et ce qu\'ils voient d\'un ticket confidentiel (rien, par défaut).',
            'managers_sources' => 'On est responsable de deux façons, les deux à la fois : on est le <strong>Responsable</strong> indiqué sur la fiche d\'autres personnes (à la main, ou depuis votre annuaire), et on a des <strong>règles de gestion</strong> définies. Cliquez sur <strong>Accès du responsable</strong> à côté de Modifier pour ouvrir une page plein écran pour cette personne, où vous pouvez lui donner tout le monde, certaines personnes, des groupes de personnes, des départements ou toute sa ligne hiérarchique, et <strong>exclure</strong> des personnes &mdash; une exclusion l\'emporte toujours, y compris sur le champ Responsable. La page indique combien de personnes elle peut voir et les liste, calculées comme si les responsables étaient déjà activés, ce qui vous permet de vérifier avant d\'activer. Cliquez sur n\'importe qui dans cette liste pour voir <strong>pourquoi</strong> le responsable peut le voir, et comment l\'en empêcher.',
            'managers_rules' => 'Un responsable ne voit jamais que des personnes de sa propre entreprise, jamais lui-même, et plus rien du tout une fois parti. Les départements sont comparés d\'après le nom saisi sur chaque personne, de sorte qu\'un département renommé cesse de correspondre &mdash; la page, ainsi que Système &rarr; Responsables, signalent une règle de département qui ne correspond à personne. Par défaut, seuls les administrateurs peuvent modifier les règles de gestion ; Système &rarr; Responsables peut l\'ouvrir à toute personne pouvant modifier des personnes.',
            'delete_heading' => '<strong>Supprimer un utilisateur</strong>',
            'delete_body' => 'Le bouton <strong>Supprimer</strong> est <strong>protégé par les clés étrangères</strong> : il refuse si l\'utilisateur est le demandeur sur des tickets ou possède des lignes dans <code>users_assets</code>, en renvoyant un message clair <em>« Impossible de supprimer : cet utilisateur est le demandeur sur N ticket(s). Réattribuez ou fermez ces tickets d\'abord. »</em>. L\'historique d\'audit ne peut jamais être rompu silencieusement.',
            'tip' => 'Tous les champs de la fenêtre modale ont le remplissage automatique du navigateur désactivé (y compris <code>autocomplete="new-password"</code> sur le champ mot de passe), afin que les identifiants enregistrés de l\'analyste ne soient pas suggérés dans un formulaire dont le seul but est de créer la fiche de <em>quelqu\'un d\'autre</em>.',
            'groups_heading' => '<strong>Groupes</strong>',
            'groups_body' => 'L\'onglet <strong>Groupes</strong> à côté de <strong>Personnes</strong> regroupe des groupes de personnes nommés &mdash; analystes et utilisateurs du portail libre-service réunis dans un même groupe. Un groupe est créé une fois ici, puis utilisé dans tout FreeITSM, ce qui permet de lui donner accès à un dossier de connaissances ou de lui attribuer une formation sans reconstituer la même liste deux fois.',
            'groups_make' => '<strong>Créez-en un</strong> avec <strong>Ajouter</strong> dans l\'onglet Groupes : un nom, et une description qu\'il vaut la peine de renseigner, car la prochaine personne doit pouvoir comprendre à quoi sert le groupe.',
            'groups_add' => '<strong>Ajoutez des personnes</strong> en les recherchant &mdash; la recherche trouve à la fois les analystes et les utilisateurs du portail, vous n\'avez donc pas besoin de savoir à quelle catégorie appartient quelqu\'un.',
            'groups_expiry' => '<strong>Donnez une date de fin à une adhésion</strong> lorsque l\'accès est temporaire. Trois ingénieurs présents sur site pour quinze jours sont ajoutés avec un dernier jour et quittent le groupe d\'eux-mêmes une fois celui-ci passé. Une adhésion expirée reste sur la liste, marquée comme expirée, afin que vous puissiez toujours voir qui avait accès et jusqu\'à quand.',
            'groups_uses' => '<strong>À quoi sert un groupe :</strong> accorder l\'accès à un dossier de connaissances, et attribuer une formation LMS à un ensemble de personnes en une fois. Les changements d\'adhésion prennent effet immédiatement &mdash; il n\'y a rien à réappliquer ensuite.',
            'groups_admin' => '<strong>Toute personne disposant du module Tickets peut voir les groupes ; seul un administrateur peut en modifier un.</strong> Ajouter quelqu\'un à un groupe peut aussi lui donner accès à un dossier de connaissances restreint, il s\'agit donc d\'un octroi d\'accès, pas d\'un simple classement.',
        ],
        'dash' => [
            'heading' => 'Tableau de bord',
            'intro' => 'Le tableau de bord des tickets fournit des analyses en un coup d\'œil avec des widgets Chart.js personnalisables. Chaque analyste dispose de sa propre disposition de tableau de bord, afin que vous puissiez vous concentrer sur les indicateurs pertinents pour votre rôle &mdash; qu\'il s\'agisse de votre charge de travail personnelle, du débit de l\'équipe ou du respect des SLA.',
            'step1' => '<strong>Ouvrez la bibliothèque</strong> &mdash; cliquez sur Modifier le tableau de bord pour passer en mode édition, puis parcourez la bibliothèque de widgets. Choisissez parmi les widgets prédéfinis ou créez le vôtre en sélectionnant un type de graphique et la propriété de données à agréger.',
            'step2' => '<strong>Ajoutez des widgets</strong> &mdash; cliquez sur le bouton + de n\'importe quel widget de la bibliothèque pour l\'ajouter à votre tableau de bord. Il apparaît immédiatement et commence à afficher les données en direct de votre base de tickets.',
            'step3' => '<strong>Configurez</strong> &mdash; cliquez sur l\'icône d\'engrenage de n\'importe quel widget pour personnaliser son titre, son type de graphique (barres, secteurs, anneau, ligne, barres empilées, multi-lignes), son filtre de période, son filtre de département et son regroupement temporel (quotidien, hebdomadaire, mensuel).',
            'step4' => '<strong>Organisez</strong> &mdash; faites glisser les widgets pour les réorganiser. Votre disposition est enregistrée par analyste afin de persister d\'une session à l\'autre.',
            'examples' => 'Exemples courants de widgets : <strong>Tickets par statut</strong> (graphique en anneau montrant ouverts, résolus et fermés), <strong>Tickets par priorité</strong> (graphique à barres du volume par gravité), <strong>Volume hebdomadaire</strong> (graphique en ligne suivant les nouveaux tickets dans le temps), et <strong>Charge de travail par analyste</strong> (barres empilées montrant les tickets actifs de chaque analyste).',
            'tip' => 'Utilisez les filtres de période sur chaque widget pour comparer les performances actuelles aux périodes précédentes. Par exemple, une vue « Ce mois-ci vs le mois dernier » vous aide à repérer tôt les tendances de volume de tickets.',
        ],
        'cal_rota' => [
            'switch_note' => 'Vous n\'utilisez pas le planning de permanence ? Désactivez-le sous <strong>Système &rarr; Modules &rarr; Disponibilité &rarr; Fonctionnalités des tickets</strong> - la page, ses paramètres et la fonction <em>qui est d\'astreinte</em> du bot War Room disparaissent, et rien n\'est supprimé.',
            'heading' => 'Calendrier &amp; planning',
            'intro' => 'Deux outils de planification aident votre équipe à rester organisée : un calendrier des tickets qui visualise la charge de travail dans le temps, et un planning du personnel pour gérer les roulements et les astreintes.',
            'cal_heading' => '<strong>Vue calendrier</strong>',
            'cal_body' => 'Le calendrier affiche chaque ticket que vous avez planifié &mdash; via <strong>Planifier le travail</strong>, disponible sur le ticket lui-même et dans le menu contextuel (clic droit) de la boîte de réception &mdash; sous forme de bloc coloré à l\'heure prévue, dessiné selon sa <strong>durée réelle</strong> plutôt qu\'une heure fixe. Les blocs rouges correspondent à la priorité <em>Haute</em>, les verts à <em>Basse</em>, le bleu à tout le reste. Utilisez <em>Aujourd\'hui</em>, les chevrons <em>&lt;</em> / <em>&gt;</em>, et le sélecteur <strong>Mois / Semaine / Jour</strong> pour naviguer.',
            'cal_scope' => '<strong>Le mien ou Tout le monde.</strong> Le calendrier s\'ouvre sur votre propre travail planifié, avec un interrupteur <strong>Tout le monde</strong> à côté des boutons d\'affichage ; votre choix est mémorisé. En mode Tout le monde, chaque ticket porte une <strong>couleur selon son propriétaire</strong>, avec une légende nommant les personnes réellement affichées à l\'écran, et survoler un ticket indique à qui il appartient sans devoir regarder ailleurs. Rien n\'est caché à personne &mdash; ce sont les mêmes tickets que ceux déjà listés dans la boîte de réception.',
            'cal_edit' => '<strong>Réorganiser le travail.</strong> <strong>Faites glisser un ticket</strong> vers un autre jour ou une autre heure : en vue Mois, il conserve son heure, et en vue Semaine et Jour, il prend l\'heure où vous le déposez, arrondie au quart d\'heure le plus proche. Sa durée ne change jamais &mdash; le glisser-déposer signifie <em>le démarrer à ce moment-là</em>, pas <em>le rallonger</em>. Vous pouvez aussi <strong>cliquer sur un ticket</strong> pour l\'ouvrir et modifier la date, l\'heure, la durée et le réglage « journée entière », ou effacer complètement sa planification. Le calendrier se <strong>rafraîchit aussi automatiquement toutes les quelques secondes</strong>, de sorte qu\'une planification faite par un collègue apparaît sans que vous ayez à recharger la page &mdash; et il suspend ce rafraîchissement pendant que vous avez un ticket ouvert ou un glisser-déposer en cours.',
            'cal_month' => '<strong>Vue Mois</strong> &mdash; la grille classique de 6 lignes avec un bandeau d\'en-tête des jours de la semaine ; chaque case de jour affiche jusqu\'à trois pastilles de tickets avec leur heure de début, plus un lien <em>+N de plus</em> qui vous amène à la vue Jour pour cette date. Aujourd\'hui est mis en évidence.',
            'cal_week' => '<strong>Vue Semaine</strong> &mdash; de lun&ndash;dim en haut, au-dessus d\'une frise chronologique verticale de 24 heures. Les tickets s\'affichent selon leur durée planifiée, si bien qu\'une intervention de 15 minutes et une reconfiguration de l\'après-midi se distinguent visuellement. Un ticket « journée entière » apparaît comme une fine barre en haut de sa journée plutôt que d\'occuper toute la colonne. La colonne d\'aujourd\'hui est mise en évidence ; l\'en-tête des jours reste fixe pendant que la grille des heures défile.',
            'cal_day' => '<strong>Vue Jour</strong> &mdash; une seule colonne haute pour le jour choisi, avec la même frise chronologique de 24 heures. Les tickets s\'affichent sous forme de blocs plus grands montrant <code>ticket_number &mdash; subject</code> et l\'heure de début ; cliquez sur l\'un d\'eux pour ouvrir ses détails ou modifier son horaire.',
            'rota_heading' => '<strong>Planning du personnel</strong>',
            'rota_body' => 'La page de planning permet aux chefs d\'équipe et aux responsables de planifier les horaires des analystes sur la semaine. Définissez les horaires de travail standard, attribuez les périodes d\'astreinte, et indiquez les congés ou absences afin que l\'équipe sache toujours qui est disponible.',
            'rota_step1' => '<strong>Consulter la grille du planning</strong> &mdash; le planning affiche les analystes sur un axe et les jours sur l\'autre, avec des blocs d\'horaires montrant la couverture en un coup d\'œil.',
            'rota_step2' => '<strong>Ajouter ou modifier des horaires</strong> &mdash; cliquez sur une case pour attribuer un type d\'horaire (par ex. Matin, Après-midi, Nuit, Astreinte). Les modifications sont enregistrées immédiatement.',
            'rota_step3' => '<strong>Planifier à l\'avance</strong> &mdash; avancez semaine par semaine pour construire le planning en amont. Cela garantit une couverture suffisante pendant les périodes de forte activité connues, les congés ou les journées de formation.',
            'rota_step4' => '<strong>Remplir plusieurs cases à la fois</strong> &mdash; faites un <strong>clic droit</strong> sur une case et choisissez <em>Copier</em> pour récupérer l\'horaire qu\'elle contient, puis faites un clic droit sur une autre et <em>Coller</em>. Pour plus d\'une case, <strong>faites glisser sur un bloc</strong> d\'entre elles (ou ctrl-clic sur les cases une par une) puis collez sur l\'ensemble. Survoler un <strong>en-tête de jour</strong> met en surbrillance toute cette journée, et survoler le <strong>nom d\'un(e) analyste</strong> met en surbrillance toute sa semaine &mdash; faites un clic droit sur l\'un ou l\'autre et collez sur l\'ensemble. Lorsque certaines cases ont déjà un horaire, le menu propose clairement les deux options &mdash; <em>Coller sur les 7</em> et <em>Coller sur les 6 cases vides</em> &mdash; afin que vous choisissiez avant de valider plutôt qu\'après. L\'écrasement vous demande une confirmation et indique combien d\'horaires seront remplacés ; le remplissage des cases vides se fait directement, puisque rien n\'est perdu. Les mêmes menus permettent aussi d\'<strong>effacer</strong> un jour, une semaine ou une sélection, là aussi après vous avoir indiqué combien d\'horaires cela supprime.',
            'rota_step5' => '<strong>Copier une journée entière ou une semaine entière pour une personne</strong> &mdash; faites un clic droit sur un <strong>en-tête de jour</strong> et choisissez <em>Copier</em> pour récupérer tous les horaires de cette journée, ou sur le <strong>nom d\'un(e) analyste</strong> pour récupérer toute sa semaine. Coller sur un autre jour, ou un(e) autre analyste, aligne exactement le résultat : les horaires absents de la copie sont effacés, de sorte que vous obtenez le jour que vous avez copié plutôt qu\'un mélange des deux. Un jour ne peut être collé que sur un autre jour, et un(e) analyste que sur un(e) autre analyste &mdash; un jour représente un horaire <em>par personne</em> et une semaine un horaire <em>par jour</em>, il n\'existe donc aucune façon cohérente de superposer l\'un à l\'autre. Essayez et le menu vous le signale, en indiquant où cela peut aller à la place.',
            'rota_step6' => '<strong>Copier une semaine entière</strong> &mdash; <strong>Copier la semaine</strong> et <strong>Coller la semaine</strong>, en haut à droite, récupèrent tous les horaires de la semaine affichée et les déposent sur une autre, la façon la plus rapide de construire un planning répétitif. Coller <em>remplace</em> la semaine cible, la confirmation vous indique donc combien d\'entrées vont être supprimées. Cela ne touche jamais que les jours et les personnes réellement affichés dans la grille.',
            'tip' => 'Combinez le calendrier et le planning pour une gestion efficace de la capacité. Si le calendrier montre un pic de tickets chaque lundi matin, assurez-vous que le planning prévoit une couverture supplémentaire sur ce créneau.',
        ],
        'settings' => [
            'heading' => 'Paramètres',
            'intro' => 'La page Paramètres est l\'endroit où vous configurez les éléments de base de votre système de tickets. Toutes les valeurs de référence, les objectifs SLA, l\'intégration des e-mails et les champs personnalisés sont gérés ici.',
            'sla_callout_title' => 'Gestion des SLA &mdash; guide complet',
            'sla_callout_body' => 'Options configurables, calendriers d\'ouverture, statuts de pause, notifications de dépassement, configuration de la tâche cron, ainsi que des exemples concrets pour les équipes sur un seul fuseau horaire ou réparties sur plusieurs. Suffisamment riche pour mériter sa propre page.',
            'card_dept_title' => 'Départements',
            'card_dept_body' => 'Créez des départements tels qu\'IT, RH et Finance. Chaque département devient un dossier dans la boîte de réception et un filtre sur le tableau de bord',
            'card_types_title' => 'Types de ticket',
            'card_types_body' => 'Définissez les types de demandes traitées par votre service : Incident, Demande de service, Problème, Changement. Les types aident les analystes à classer le travail',
            'card_type_rules_title' => 'Type des nouveaux tickets',
            'card_type_rules_body' => 'Sous Types de ticket, donnez à chaque nouveau ticket un type lorsque personne n\'en choisit : un type par défaut, et des règles avant lui - selon son mode d\'arrivée (e-mail, portail, chat web, téléphone, surveillance...), la boîte aux lettres, l\'origine, le département, des mots du sujet ou le domaine du demandeur. La première règle qui correspond l\'emporte ; Essayer montre quel type un ticket recevrait',
            'card_priorities_title' => 'Priorités',
            'card_priorities_body' => 'Définissez les niveaux de priorité avec leurs noms, couleurs et ordres de tri. Chaque priorité est liée à un objectif SLA de réponse et de résolution',
            'card_statuses_title' => 'Statuts',
            'card_statuses_body' => 'Personnalisez les étapes du cycle de vie des tickets. Les statuts par défaut incluent Nouveau, Ouvert, En cours, En attente, Résolu et Fermé',
            'card_categories_title' => 'Catégories',
            'card_categories_body' => 'Regroupez les tickets par domaine technique : Matériel, Logiciel, Réseau, Accès. Les catégories alimentent les répartitions dans les rapports',
            'card_sla_title' => 'Objectifs SLA',
            'card_sla_body' => 'Définissez les délais cibles de réponse et de résolution par priorité. Les compteurs SLA apparaissent sur les tickets et déclenchent les alertes de dépassement',
            'card_email_title' => 'Importation des e-mails',
            'card_email_body' => 'Connectez une boîte aux lettres (Exchange, Microsoft 365) pour importer automatiquement les e-mails sous forme de nouveaux tickets. Les réponses viennent s\'ajouter aux tickets existants',
            'card_custom_title' => 'Champs personnalisés',
            'card_custom_body' => 'Ajoutez vos propres champs aux tickets pour les données que votre organisation doit saisir et qui ne sont pas couvertes par les champs par défaut',
            'card_templates_title' => 'Modèles d\'e-mail',
            'card_templates_body' => 'Configurez les modèles de notification envoyés aux utilisateurs finaux lors de la création, la mise à jour, la résolution des tickets, ou pour l\'enquête CSAT. Intégrez des codes de fusion comme [requester_name] et [csat_link]',
            'card_checklists_title' => 'Listes de contrôle',
            'card_checklists_body' => 'Décidez ce qui se passe quand quelqu\'un ferme un ticket qui a encore des étapes obligatoires de la liste de contrôle en attente : <strong>avertir</strong> et enregistrer une note interne nommant les étapes et qui a fermé le ticket, ou <strong>bloquer</strong> la fermeture jusqu\'à ce qu\'elles soient terminées. Appliqué partout où un ticket peut être fermé - actions groupées, API REST et automatisation par workflow incluses',
            'card_custom_fields_title' => 'Champs personnalisés',
            'card_custom_fields_body' => 'Définissez les détails supplémentaires dont un type de ticket a besoin - texte, nombre, date, oui / non, liste déroulante de vos propres options, adresse web ou e-mail - et reliez chacun à certains types de ticket ou à tous. Chaque champ choisit s\'il doit être renseigné <strong>lors de l\'enregistrement du ticket</strong> (le formulaire Nouveau ticket, l\'API REST et, si demandé, le portail), <strong>avant sa fermeture</strong> (selon la règle des champs obligatoires), ou les deux, et si le <strong>demandeur est interrogé</strong> à ce sujet sur le portail - où un sélecteur de type de ticket apparaît dès qu\'il modifie ce qui est demandé. Les réponses s\'affichent dans le panneau des propriétés du ticket et dans son historique. Changer le type d\'un ticket masque les réponses que son nouveau type n\'a pas, sans jamais les supprimer',
            'card_mandatory_title' => 'Champs obligatoires',
            'card_mandatory_body' => 'Cochez les champs qui doivent être renseignés avant qu\'un ticket puisse être fermé - catégorie, code de résolution, propriétaire, etc. Choisissez ensuite ce qui se passe lorsque quelqu\'un ferme un ticket avec un champ vide : <strong>avertir</strong>, <strong>avertir et envoyer un e-mail</strong> à une personne telle qu\'un responsable de la livraison de services, ou <strong>refuser</strong> la fermeture. Un interrupteur distinct enregistre cela sur le ticket sous forme de note interne. Un champ désactivé pour une entreprise n\'est jamais obligatoire, et la fusion de tickets ne le déclenche jamais. Appliqué partout où un ticket peut être fermé - actions groupées, API REST et automatisation des workflows incluses',
            'card_cleanup_title' => 'Nettoyage des réponses par IA',
            'card_cleanup_body' => 'Clé Anthropic + modèle + ton pour le bouton ✨ Nettoyer de l\'éditeur de réponse. Clé distincte des autres fonctionnalités IA pour une facturation détaillée',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Mode d\'envoi (désactivé / automatique / manuel), délai, limite d\'un envoi par ticket, échelle (étoiles ou émojis). Voir la section 6 pour le déroulement complet',
            'email_heading' => '<strong>L\'importation des e-mails en détail</strong>',
            'email_body' => 'La fonction d\'importation des e-mails se connecte à votre boîte aux lettres partagée et récupère les nouveaux messages sous forme de tickets. Lorsqu\'un utilisateur final envoie un e-mail à votre adresse de support (par ex. support@yourcompany.com), FreeITSM crée un ticket dont le titre est l\'objet de l\'e-mail et la description le corps du message. Si l\'expéditeur répond à un e-mail de notification, la réponse est rattachée au ticket existant plutôt que de créer un doublon.',
            'email_step1' => '<strong>Configurer la boîte aux lettres</strong> &mdash; rendez-vous dans Paramètres et saisissez vos identifiants Exchange ou Microsoft 365. L\'authentification OAuth est prise en charge pour des connexions sécurisées, sans mot de passe.',
            'email_step2' => '<strong>Définir l\'intervalle de vérification</strong> &mdash; choisissez la fréquence à laquelle FreeITSM vérifie la boîte aux lettres pour de nouveaux messages. Des intervalles plus courts accélèrent la création des tickets.',
            'email_step3' => '<strong>Définir les valeurs par défaut</strong> &mdash; définissez le département, le type et la priorité par défaut pour les tickets créés par e-mail. Les analystes peuvent les ajuster après l\'importation.',
            'email_thread_note' => '<strong>Une réponse sans numéro de ticket</strong> &mdash; chaque e-mail envoyé par FreeITSM porte le numéro du ticket, donc une réponse à celui-ci retrouve toujours son ticket. Lorsque quelqu\'un répond à son <em>propre</em> premier e-mail à la place (pour ajouter une pièce jointe oubliée, par exemple), il n\'y a pas de numéro à trouver, et par défaut cette réponse crée un nouveau ticket. Réglez Tickets &rarr; Paramètres &rarr; Général &rarr; <strong>Une réponse sans numéro de ticket</strong> sur <strong>Rejoint le ticket auquel appartient sa conversation</strong> et elle est ajoutée au ticket ouvert par ce premier e-mail, en le rouvrant s\'il était fermé (lorsque la réouverture est activée). Seuls les e-mails de la même boîte aux lettres sont comparés.',
            'email_reply_to_note' => '<strong>À qui répond Répondre</strong> &mdash; par défaut, la zone de réponse est adressée à la personne du message que vous lisez. Si des collègues du demandeur rejoignent le fil et que vous préférez toujours répondre au demandeur, réglez Tickets &rarr; Paramètres &rarr; Général &rarr; <strong>La réponse va à</strong> sur <strong>Le demandeur du ticket</strong>. Vous pouvez toujours modifier l\'adresse avant l\'envoi.',
            'email_sent_copy_note' => '<strong>Une copie des e-mails envoyés dans le dossier Envoyés (IMAP basique)</strong> - une boîte aux lettres IMAP basique envoie via SMTP, qui ne conserve aucune copie, donc toute personne lisant la même boîte dans Thunderbird ou en webmail ne verrait pas ce que le service d\'assistance a envoyé. Modifiez la boîte aux lettres et activez <strong>Enregistrer une copie des e-mails envoyés</strong>, juste sous <em>Utiliser l\'identifiant IMAP pour l\'envoi</em> : chaque réponse, e-mail de modèle, e-mail de workflow et e-mail système qu\'elle envoie est alors aussi placé dans son dossier Envoyés, marqué comme lu. Les notifications internes aux analystes ne sont jamais classées. Laissez <strong>Dossier Envoyés</strong> vide pour utiliser le dossier que votre serveur de messagerie marque comme Envoyés, ou saisissez son nom. Laissez l\'interrupteur désactivé si votre serveur de messagerie classe déjà les e-mails envoyés (Gmail et Microsoft 365 le font, ainsi que certains hébergeurs) - vous obtiendriez deux copies. <strong>Tester</strong> indique dans quel dossier la copie est allée. Si une copie ne peut pas être enregistrée, l\'e-mail est tout de même parti, et la raison figure dans l\'onglet <strong>Activité</strong> &rarr; <strong>Sortant</strong> de la boîte aux lettres sous <em>Copie vers le dossier Envoyés</em>.',
            'tip' => 'Utilisez les modèles d\'e-mail pour conserver un ton professionnel et cohérent dans toutes les communications avec les utilisateurs finaux. Les modèles prennent en charge des variables dynamiques pour la référence du ticket, le nom du demandeur, le nom de l\'analyste et le statut.',
            'closemsg_heading' => '<strong>Un message ponctuel à la fermeture d\'un ticket</strong>',
            'closemsg_body' => 'Placez <code>[ticket_closed_message]</code> n\'importe où dans un modèle <strong>Ticket fermé</strong> actif et, à partir de là, le passage d\'un ticket à un statut fermé demande à l\'analyste une phrase - <em>&ldquo;le chargeur de secours est sur votre bureau&rdquo;</em>, <em>&ldquo;fermeture comme convenu au téléphone&rdquo;</em>. Ce qu\'il ou elle saisit s\'insère exactement à l\'endroit où vous avez placé ce repère, ce qui vous laisse le contrôle du texte qui l\'entoure. Ce n\'est pas un paramètre et rien ne le conserve : une note, un ticket, un e-mail. Ne rien saisir et la ligne n\'apparaît tout simplement pas - ni espace, ni ponctuation superflue.',
            'closemsg_note' => '<strong>L\'invite n\'apparaît que lorsque le repère est réellement présent dans le modèle.</strong> Sans lui, tout ce qu\'un analyste saisirait serait silencieusement ignoré, et chaque service qui ne souhaite pas cette fonction gagnerait un clic supplémentaire à chaque fermeture. Elle s\'active donc d\'elle-même dès que vous la configurez, et reste invisible tant que vous ne l\'avez pas fait.',
            'cat_heading' => '<strong>Catégories, et les deux champs qui les accompagnent</strong>',
            'cat_body' => 'Le <em>type</em> d\'un ticket indique de quel genre de chose il s\'agit ; une <em>catégorie</em> indique de quoi il parle. Construisez la liste sous <strong>Paramètres &rarr; Catégories</strong>, ainsi que les interrupteurs qui décident si tout cela apparaît ou non sur un ticket.',
            'cat_card_one_title' => 'Catégorie',
            'cat_card_one_body' => 'Ce sous quoi le ticket a été signalé, choisi au moment de sa création. Un ticket en porte exactement une, si bien qu\'un rapport par catégorie totalise toujours le nombre de tickets réellement reçus.',
            'cat_card_close_title' => 'Catégorie à la fermeture',
            'cat_card_close_body' => 'La même liste est proposée à nouveau lorsque le ticket se termine. En général, l\'analyste se contente de la confirmer &mdash; elle prend tout son sens sur les cas où la première estimation était fausse, ce qui permet de découvrir que douze de vos trente-sept « problèmes d\'imprimante » relevaient en réalité du réseau.',
            'cat_card_res_title' => 'Code de résolution',
            'cat_card_res_body' => 'Comment le ticket s\'est terminé plutôt que de quoi il parlait &mdash; « Résolu à distance », « Formation dispensée », « Aucun défaut constaté ». Dix codes pertinents sont présents dès le départ et vous pouvez tous les modifier.',
            'cat_rule_off' => '<strong>Les trois sont désactivées au départ.</strong> Construisez d\'abord votre liste, puis activez celles que vous voulez. Chacune peut être réglée différemment pour chaque entreprise.',
            'cat_rule_levels' => 'Les catégories peuvent avoir des sous-catégories sur trois niveaux au maximum, et aucun niveau n\'est obligatoire.',
            'cat_rule_type' => 'Une catégorie peut être liée à un seul type de ticket, de sorte que « Intégration utilisateur » n\'est proposée que sur une demande de service. Le lien appartient à la catégorie de premier niveau, et ses sous-catégories le suivent.',
            'cat_rule_typechange' => '<strong>Changer le type d\'un ticket efface une catégorie qui appartenait à l\'ancien type</strong>, et le signale à l\'écran. Une catégorie non liée à un type survit au changement.',
            'cat_rule_portal' => 'Cochez <em>Les clients peuvent choisir cette catégorie</em> pour proposer une catégorie dans le portail libre-service. Les demandeurs voient une liste courte, en langage clair, tandis que les analystes voient l\'arborescence complète.',
            'cat_rule_retire' => 'Désactivez une catégorie pour la retirer &mdash; elle reste sur les tickets qui l\'ont déjà et cesse d\'être proposée sur les nouveaux. C\'est presque toujours préférable à la suppression, qui est refusée tant que quelque chose l\'utilise encore.',
            'cat_rule_report' => 'Les trois peuvent être représentées sous forme de graphiques sur le tableau de bord des tickets. Les deux graphiques de catégories remontent au niveau supérieur, et les tickets sans valeur définie sont comptés comme <em>Non catégorisé</em> plutôt que masqués.',
            'cat_rule_workflow' => '<strong>Catégories dans les workflows :</strong> un workflow peut router les tickets par catégorie - une condition <em>Catégorie</em> fonctionne sur chaque déclencheur de ticket, et le déclencheur <em>La catégorie d\'un ticket change</em> capte un ticket catégorisé lors du triage. Par défaut, une condition nommant une catégorie correspond aussi à ses sous-catégories, donc « Matériel » capte « Matériel &rarr; Portable » ; choisissez <strong>Elle correspond uniquement à cette catégorie</strong> dans <strong>Tickets &rarr; Paramètres &rarr; Catégories &rarr; Catégories dans les workflows</strong> pour que chaque workflow nomme chaque sous-catégorie voulue. Lorsque le changement de type d\'un ticket efface sa catégorie, le déclencheur se déclenche aussi.',
            'cat_tip' => 'Si vous ne savez pas par où commencer, laissez les catégories vides et activez uniquement le <strong>Code de résolution</strong>. C\'est le champ qui change le plus rapidement votre façon de travailler &mdash; si un cinquième de vos tickets revient avec « Formation dispensée », c\'est un problème de documentation, pas un problème informatique.',
        ],
        'tips' => [
            'heading' => 'Astuces rapides',
            'search_title' => 'Rechercher partout',
            'search_body' => 'La fenêtre de recherche vérifie les références de ticket, les objets, les noms des demandeurs et les adresses e-mail. Utilisez-la pour retrouver rapidement les tickets liés lorsqu\'un utilisateur appelle au sujet d\'un problème existant.',
            'sla_title' => 'Surveillez vos SLA',
            'sla_body' => 'Les minuteurs SLA sont visibles sur chaque ticket dans le volet de lecture. Les indicateurs colorés passent à l\'orange lorsqu\'un dépassement approche et au rouge lorsque l\'objectif n\'a pas été atteint, afin que vous puissiez prioriser en conséquence.',
            'reply_title' => 'Répondre depuis la boîte de réception',
            'reply_body' => 'Vous n\'avez pas besoin d\'ouvrir votre client de messagerie pour répondre à un utilisateur final. Utilisez le bouton Répondre dans le volet de lecture pour envoyer un message directement. Il s\'ajoute automatiquement au fil du ticket.',
            'reply_to_title' => 'À qui va Répondre',
            'reply_to_body' => 'Répondre est adressé à la personne du message que vous lisez. Si vous préférez que ce soit toujours le demandeur du ticket, modifiez <strong>La réponse va à</strong> dans Tickets &rarr; Paramètres &rarr; Général. Dans les deux cas, vous pouvez modifier l\'adresse, ou ajouter des personnes en Cc, avant l\'envoi.',
            'trail_title' => 'Consultez l\'historique d\'activité',
            'trail_body' => 'Avant de traiter un ticket, parcourez son historique d\'activité. Les notes des analystes précédents, les e-mails et les modifications de champs vous donnent tout le contexte nécessaire pour éviter de demander à l\'utilisateur de répéter des informations.',
            'dash_title' => 'Tableau de bord pour les managers',
            'dash_body' => 'Créez un tableau de bord avec des widgets pour les taux de conformité SLA, le temps de résolution moyen et les tickets par département. Partagez-le lors des réunions d\'équipe pour favoriser l\'amélioration continue.',
            'rota_title' => 'Planifiez avec le planning',
            'rota_body' => 'Remplissez le planning au moins deux semaines à l\'avance. Associé à la vue calendrier, il vous aide à repérer les manques de couverture avant qu\'ils ne posent problème pour les délais de réponse.',
            'drag_title' => 'Glissez pour trier',
            'drag_body' => 'Glissez les tickets depuis la liste vers des dossiers pour les mettre à jour sans les ouvrir. Les sous-dossiers Département + Statut mettent à jour les deux à la fois. Le déploiement automatique au survol permet d\'atteindre les statuts imbriqués en cours de glissement.',
            'dbl_title' => 'Double-cliquez pour le plein écran',
            'dbl_body' => 'Un simple clic affiche un aperçu du ticket dans le volet de lecture ; un double clic l\'ouvre en mode plein écran pour un travail concentré. Cliquez sur l\'icône d\'agrandissement à côté de l\'objet pour revenir en arrière.',
            'rightclick_title' => 'Clic droit pour les actions rapides',
            'rightclick_body' => 'Faites un clic droit sur n\'importe quel ticket pour changer le statut, la priorité ou l\'assigné en un clic, lier un élément de la CMDB ou enregistrer du temps, le tout sans quitter le ticket que vous êtes en train de lire.',
            'ai_title' => 'Laissez l\'IA améliorer votre réponse',
            'ai_body' => 'Saisissez un brouillon (ou simplement des points clés) et cliquez sur <strong>✨ Nettoyer</strong> &mdash; Claude le réécrit sous forme d\'e-mail soigné, avec formule de politesse, corrections grammaticales et signature. Le lien d\'annulation reste visible pendant 30 secondes.',
            'feedback_title' => 'Demandez un retour',
            'feedback_body' => 'Activez le CSAT dans <strong>Paramètres &rarr; CSAT</strong> pour sonder automatiquement les demandeurs à la fermeture de leurs tickets. Les tendances par analyste se trouvent dans <code>tickets/csat/</code> &mdash; précieuses pour les entretiens de développement.',
            'precreate_title' => 'Pré-créez les utilisateurs finaux',
            'precreate_body' => 'Le bouton de navigation <strong>Utilisateurs</strong> vous permet d\'ajouter un utilisateur avant qu\'il n\'ait besoin de créer un ticket &mdash; laissez le mot de passe vide et il pourra récupérer son compte lui-même via le portail libre-service.',
        ],
        'companies' => [
            'heading' => 'Entreprises &amp; routage des e-mails',
            'intro' => 'Lorsque votre installation sert plusieurs entreprises (par exemple un prestataire informatique gérant plusieurs clients), les tickets de chaque entreprise sont conservés séparément. Cette section explique comment les e-mails entrants trouvent la bonne entreprise.',
            'switcher_body' => 'Un <strong>sélecteur d\'entreprise</strong> apparaît dans l\'en-tête. Il définit l\'entreprise dans laquelle vous travaillez &mdash; la liste des tickets, les dossiers et les compteurs n\'affichent que cette entreprise, et tout ticket que vous créez lui est rattaché. Le personnel ayant accès à plusieurs entreprises peut basculer entre elles ; l\'entreprise en cours est toujours affichée pour éviter de répondre dans le mauvais contexte. Gérez les entreprises elles-mêmes dans <strong>Système &rarr; Entreprises</strong>.',
            'mailboxes_heading' => 'Chaque boîte aux lettres est de l\'un de ces deux types &mdash; c\'est ce qui détermine le routage :',
            'card_pinned_title' => 'Boîte aux lettres dédiée',
            'card_pinned_body' => 'Dédiée à une seule entreprise (par exemple la boîte <code>itsupport@</code> propre à un client). <strong>Tout</strong> son courrier est rattaché à cette entreprise &mdash; l\'expéditeur est ignoré &mdash; et les réponses en repartent, de sorte que le client voit son propre service d\'assistance de bout en bout.',
            'card_shared_title' => 'Boîte aux lettres d\'accueil partagée',
            'card_shared_body' => 'Une seule adresse au service de plusieurs entreprises (par exemple l\'unique <code>support@theprovider.com</code> d\'un prestataire). Elle ne peut pas déterminer l\'entreprise à partir de la seule adresse, elle se base donc sur <strong>qui a envoyé l\'e-mail</strong>. C\'est la configuration recommandée pour un prestataire ayant de nombreux clients.',
            'routing_heading' => 'Comment une boîte aux lettres d\'accueil partagée choisit l\'entreprise',
            'routing_body' => 'Pour chaque e-mail entrant, elle essaie ces règles dans l\'ordre, et la première correspondance l\'emporte :',
            'flow_reply' => 'Réponse à un ticket',
            'flow_sender' => 'Expéditeur connu',
            'flow_domain' => 'Domaine connu',
            'flow_triage' => 'Tri',
            'rule_reply' => '<strong>1. Réponse à un ticket existant</strong> &mdash; reconnu grâce à sa référence, l\'e-mail rejoint ce ticket et conserve son entreprise.',
            'rule_sender' => '<strong>2. Une adresse d\'expéditeur spécifique</strong> associée à une entreprise (par exemple <code>jane@gmail.com</code> &rarr; Acme) &mdash; cette entreprise. Vérifiée avant le domaine, ce qui fonctionne même pour les adresses personnelles ou de messagerie web.',
            'rule_domain' => '<strong>3. Le domaine de l\'expéditeur</strong> associé à une entreprise (par exemple toute personne <code>@acme.com</code> &rarr; Acme) &mdash; cette entreprise.',
            'rule_triage' => '<strong>4. Aucune correspondance</strong> &mdash; l\'e-mail part dans la file de <strong>tri</strong> plutôt que d\'être perdu (voir ci-dessous).',
            'keys_heading' => 'Domaines &amp; expéditeurs spécifiques (définis par entreprise dans Système &rarr; Entreprises)',
            'keys_body' => 'Ce sont les critères sur lesquels se base une boîte aux lettres d\'accueil partagée. Chaque entreprise répertorie les domaines de messagerie qu\'elle possède et, en option, des adresses d\'expéditeur individuelles.',
            'card_domains_title' => 'Domaines de messagerie',
            'card_domains_body' => 'Les domaines que possède une entreprise (acme.com, acme.co.uk). Tout expéditeur sur un domaine enregistré est acheminé vers cette entreprise. Un domaine n\'appartient qu\'à une seule entreprise.',
            'card_senders_title' => 'Expéditeurs spécifiques',
            'card_senders_body' => 'Adresses individuelles associées à une entreprise, vérifiées avant le domaine. À utiliser pour un indépendant ou un petit client qui écrit depuis une adresse personnelle.',
            'card_public_title' => 'Fournisseurs publics',
            'card_public_body' => 'Gmail, Outlook, Yahoo et autres ne peuvent pas être associés en tant que domaine (de nombreuses personnes sans lien les partagent) &mdash; associez plutôt l\'adresse exacte en tant qu\'expéditeur spécifique.',
            'triage_heading' => 'La file de tri &mdash; le filet de sécurité',
            'triage_body' => 'Lorsqu\'un e-mail arrivé sur une boîte partagée ne correspond à aucune entreprise, il atterrit dans <strong>Tri</strong> (accessible depuis le sélecteur d\'entreprise, avec un compteur en direct) plutôt que d\'être perdu. Chaque élément affiche l\'expéditeur, le domaine, l\'objet et la boîte aux lettres de réception. Rattachez-le à une entreprise en une seule étape :',
            'triage_create' => 'Choisissez une entreprise existante, ou créez-en une nouvelle sur-le-champ.',
            'triage_assign' => 'Pour un domaine normal, vous pouvez éventuellement <strong>router ce domaine</strong> vers l\'entreprise ; pour une adresse publique ou de messagerie web, vous pouvez éventuellement <strong>toujours rattacher cet expéditeur</strong> à celle-ci.',
            'triage_sweep' => 'Chaque choix <em>balaie</em> aussi la file : il déplace tous les autres e-mails en attente de ce domaine ou de cette adresse, et achemine automatiquement le courrier futur &mdash; vous ne triez donc un expéditeur donné qu\'une seule fois.',
            'triage_tip' => 'Rien n\'est jamais perdu. Le courrier sans correspondance attend dans le tri jusqu\'à ce que quelqu\'un le rattache ; en attendant, un ticket non rattaché s\'affiche sous l\'entreprise par défaut.',
            'test_heading' => 'Testez votre routage avant la mise en service',
            'test_body' => 'Dans <strong>Système &rarr; Test de routage des e-mails</strong>, vous pouvez simuler l\'arrivée d\'un e-mail &mdash; choisissez une boîte aux lettres, saisissez une adresse d\'expéditeur &mdash; et voir exactement dans quelle entreprise le nouveau ticket atterrirait (ou s\'il partirait en tri) et quelle règle en a décidé. Cela ne crée rien ; cela ne fait que lire vos paramètres.',
            'settings_heading' => 'Paramètres : partagés par défaut, adaptés là où c\'est nécessaire',
            'settings_body' => 'Certains de ces paramètres peuvent être <strong>adaptés par entreprise</strong> ; d\'autres restent partagés volontairement. Lorsqu\'un paramètre est une simple liste d\'options &mdash; comme les <strong>types de ticket</strong> et les <strong>origines</strong> &mdash; basculez dans le contexte d\'une entreprise et vous verrez les valeurs par défaut partagées (chacune avec une icône œil pour masquer celles qu\'elle n\'utilise pas) ainsi que celles qu\'elle a ajoutées pour elle-même. Vous ne pouvez pas masquer ou supprimer une option tant que des tickets ouverts l\'utilisent encore, et les valeurs par défaut partagées elles-mêmes se modifient depuis l\'entreprise MSP / par défaut.',
            'settings_custom_title' => 'Adapté par entreprise',
            'settings_custom_body' => 'Types de ticket &amp; origines (dès maintenant), ainsi que catégories, SLA &amp; horaires d\'ouverture (à venir) &mdash; des éléments qui diffèrent réellement d\'un client à l\'autre.',
            'settings_global_title' => 'Partagé entre toutes les entreprises',
            'settings_global_body' => 'Les statuts et les priorités restent identiques partout, afin que les rapports et les SLA inter-entreprises restent cohérents ; il en va de même pour vos équipes, votre planning et vos boîtes aux lettres &mdash; c\'est votre propre organisation, pas celle d\'un client.',
            'allview_heading' => '<strong>Un seul tableau pour toutes les entreprises</strong>',
            'allview_body' => 'Le sélecteur d\'entreprise dans l\'en-tête propose une option <strong>Toutes les entreprises</strong>. Tous les tickets que vous êtes autorisé à voir apparaissent dans une seule liste, chaque ligne affichant l\'entreprise à laquelle elle appartient &mdash; utile lorsque vous soutenez plusieurs entités et souhaitez une vue d\'ensemble de la journée sans perdre de vue à qui appartient quoi.',
            'allview_card_scope_title' => 'Cela n\'accorde rien de nouveau',
            'allview_card_scope_body' => '« Toutes » signifie chaque entreprise que vous pouviez déjà consulter une à une. Un analyste qui soutient deux de vos trois entités voit exactement ces deux-là, et un analyste rattaché à une seule entreprise ne voit que celle-ci.',
            'allview_card_props_title' => 'Chaque entité reste distincte',
            'allview_card_props_body' => 'Ouvrez un ticket : son type, son origine, sa catégorie et sa liste de résolutions sont ceux appartenant à <em>cette</em> entreprise &mdash; ainsi, une catégorie qu\'une entité possède et qu\'une autre n\'a pas ne peut jamais être appliquée au mauvais ticket.',
            'allview_card_new_title' => 'Les nouveaux tickets demandent quelle entreprise',
            'allview_card_new_body' => 'Il n\'y a pas d\'entreprise active unique à présumer, et ce choix détermine le numéro de ticket, la boîte aux lettres d\'où partent les réponses et le SLA applicable. La liste des types se remplit une fois votre choix effectué.',
            'allview_rule_chip' => 'Un ticket arrivé par e-mail ou via le portail sans avoir encore été routé est marqué <strong>Non routé</strong> plutôt qu\'affiché sous Défaut, afin qu\'il ressorte pour le tri.',
            'allview_rule_reply' => 'Les réponses partent toujours de la boîte aux lettres où le ticket est arrivé &mdash; cela suit le ticket, pas la vue, de sorte qu\'un tableau combiné ne peut jamais envoyer depuis la mauvaise adresse.',
            'allview_rule_knowledge' => '<strong>Demander à l\'IA</strong> effectue une recherche dans toutes les entreprises que vous pouvez voir lorsque la vue combinée est activée, au lieu d\'une seule. Les articles partagés avec toutes les entreprises sont inclus dans tous les cas.',
            'allview_rule_trash' => '<strong>Vider la corbeille ne s\'applique jamais à plusieurs entreprises à la fois.</strong> Cela concerne toujours la seule entreprise que vous avez choisie en dernier, car « tout supprimer dans la corbeille » sur plusieurs entités à la fois n\'est jamais ce que l\'on veut dire par là.',
            'allview_rule_other' => 'Seule la liste des tickets s\'élargit. Les actifs, les changements, les tâches et la CMDB continuent d\'afficher une seule entreprise à la fois &mdash; basculez vers cette entreprise pour y travailler.',
            'privacy_heading' => 'Les tickets de chaque entreprise restent privés',
            'privacy_body' => 'Lorsque vous travaillez dans le contexte d\'une entreprise, vous ne voyez jamais que les tickets de <strong>cette</strong> entreprise &mdash; dans la liste, dans la recherche, sur les tableaux de bord, et sur chaque ticket que vous ouvrez (y compris ses e-mails, pièces jointes, notes et historique). Un membre du personnel ne peut accéder à un ticket que s\'il a reçu l\'accès à son entreprise (vous choisissez les entreprises de chaque analyste dans Système &rarr; Analystes, ou en accordez à toute une équipe dans Système &rarr; Équipes), de sorte qu\'il n\'y a aucun moyen de s\'égarer dans les données d\'un autre client. Cette séparation est appliquée partout en coulisses, pas simplement masquée à la vue. Sur une installation à entreprise unique, c\'est automatique et invisible &mdash; il n\'y a qu\'une seule entreprise, donc tout lui appartient simplement.',
            'tip' => 'Sur une installation à entreprise unique, rien de tout cela n\'apparaît &mdash; il n\'y a qu\'une seule entreprise, chaque ticket lui appartient, et il n\'y a ni sélecteur ni tri. Ces fonctionnalités ne s\'activent que lorsqu\'une deuxième entreprise existe.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'Gestion des SLA',
        'back_link' => '&larr; Retour au guide des tickets',
        'sidebar_title' => 'Guide SLA',
        'hero_title' => 'Gestion des SLA',
        'hero_sub' => 'Objectifs de réponse et de résolution tenant compte des heures ouvrées, avec des notifications de dépassement par département',
        'nav' => [
            'overview' => 'Vue d\'ensemble',
            'building_blocks' => 'Éléments de base',
            'behaviour_settings' => 'Paramètres de comportement',
            'breach_notifications' => 'Notifications de dépassement',
            'cron_setup' => 'Configuration de la tâche cron',
            'worked_examples' => 'Exemples concrets',
            'troubleshooting' => 'Dépannage',
        ],
        'overview' => [
            'heading' => 'Vue d\'ensemble',
            'sub' => 'Ce que sont les SLA, pourquoi ils comptent, et comment fonctionne le moteur FreeITSM dans les grandes lignes.',
            'p1' => 'Un accord de niveau de service (SLA) est un engagement sur la rapidité avec laquelle votre équipe répond à un ticket et le résout. FreeITSM suit deux horloges par ticket : le <strong>temps de réponse</strong> (durée entre la création du ticket et la première action d\'un analyste) et le <strong>temps de résolution</strong> (durée entre la création du ticket et sa fermeture). Les deux objectifs sont définis par priorité &mdash; ainsi une priorité P1 peut avoir 30 minutes pour la réponse et 4 heures pour la résolution, tandis qu\'une priorité P4 peut avoir 8 heures ouvrées et 5 jours ouvrés.',
            'switch_note' => 'Vous n\'utilisez pas les SLA ? Désactivez SLA sous <strong>Système &rarr; Modules &rarr; Disponibilité &rarr; Fonctionnalités des tickets</strong> : les chronomètres, les avertissements de dépassement et les déclencheurs de workflow SLA s\'arrêtent, tandis que les calendriers d\'ouverture restent pour les horaires du chat web. La réactivation demande s\'il faut envoyer les avertissements manqués pendant la désactivation, ou les ignorer.',
            'p2' => 'Le moteur de SLA de FreeITSM repose sur quatre choix de conception à connaître :',
            'choice_business' => '<strong>Heures ouvrées, pas temps réel.</strong> Un ticket P2 créé à 16h30 avec un objectif de réponse d\'une heure n\'est pas en dépassement à 17h30 si le bureau ferme à 17h. L\'horloge reprend à 9h le jour ouvré suivant. C\'est la norme du secteur et le seul modèle équitable lorsque les analystes rentrent chez eux le soir.',
            'choice_pause' => '<strong>Peut être mise en pause.</strong> Lorsqu\'un ticket est dans un statut marqué « Pause SLA » (comme <em>En attente de réponse</em> ou <em>En attente</em>), l\'horloge s\'arrête. Elle reprend lorsque le ticket revient à un statut actif.',
            'choice_compute' => '<strong>Calculé à la lecture, jamais stocké.</strong> Le moteur recalcule l\'état du SLA à partir du journal d\'audit du ticket à chaque consultation. Il n\'existe aucun compteur stocké susceptible de se désynchroniser. Si vous modifiez plus tard les horaires d\'un calendrier d\'entreprise, le SLA de chaque ticket historique est recalculé selon les nouveaux horaires dès sa prochaine consultation.',
            'choice_cutoff' => '<strong>Date d\'entrée en vigueur.</strong> Une date « Appliquer les SLA à partir de », contrôlée par un administrateur, évite que les tickets existants de votre système ne se retrouvent soudainement en dépassement rétroactif lorsque vous activez les SLA. Seuls les tickets créés à partir de cette date sont suivis.',
            'tip' => 'Si vous découvrez ITIL : le temps de réponse concerne la prise en charge (quelqu\'un s\'en est occupé) ; le temps de résolution concerne l\'achèvement (le problème de l\'utilisateur est réglé). Les deux horloges fonctionnent indépendamment et ont des objectifs différents.',
        ],
        'blocks' => [
            'heading' => 'Les quatre éléments de base',
            'sub' => 'Configurez ces quatre éléments et le suivi des SLA devient opérationnel. Tout le reste est un affinage facultatif.',
            'cal_heading' => '1. Calendriers d\'entreprise',
            'cal_intro' => 'Un calendrier définit les horaires d\'ouverture de votre service desk. Chaque calendrier comporte :',
            'cal_tz' => '<strong>Fuseau horaire</strong> &mdash; un identifiant de fuseau horaire IANA (par exemple <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Les passages à l\'heure d\'été/hiver sont gérés automatiquement.',
            'cal_hours' => '<strong>Heures ouvrées hebdomadaires</strong> &mdash; une ligne par jour de la semaine avec une case à cocher Ouvert et des heures de début / fin. Par défaut, les nouveaux calendriers sont réglés sur lun.-ven. 09:00-17:00, sam./dim. fermé. Une ligne sans la case Ouvert cochée signifie que le service desk est fermé ce jour-là.',
            'cal_holidays' => '<strong>Jours fériés</strong> &mdash; une date et un nom facultatif. Les jours fériés prévalent sur le schéma hebdomadaire (le service desk est fermé même si le jour tombe un lundi).',
            'cal_default' => '<strong>Indicateur par défaut</strong> &mdash; un seul calendrier est défini par défaut. Les nouvelles priorités l\'héritent, sauf indication contraire.',
            'cal_outro' => 'Vous pouvez créer autant de calendriers que nécessaire &mdash; un par bureau, un par équipe, un pour les clients VIP avec des horaires étendus. Ils sont partagés par les objectifs de SLA et le moteur de vérification des dépassements.',
            'prio_heading' => '2. Priorités et objectifs de SLA',
            'prio_intro' => 'Dans l\'onglet Priorités (ou via le tableau des objectifs de SLA de l\'onglet SLA), chaque priorité peut avoir :',
            'prio_response' => '<strong>Objectif de réponse (minutes)</strong> &mdash; le délai avant la première action d\'un analyste.',
            'prio_resolution' => '<strong>Objectif de résolution (minutes)</strong> &mdash; le délai avant la fermeture du ticket.',
            'prio_calendar' => '<strong>Calendrier</strong> &mdash; le calendrier d\'entreprise sur lequel se base l\'horloge de cette priorité. Laissez vide pour utiliser le calendrier par défaut.',
            'prio_outro' => 'Laisser les deux champs d\'objectif vides désactive entièrement le suivi du SLA pour cette priorité &mdash; utile pour une priorité « Informatif » ou « Backlog » où il n\'y a pas de contrainte de temps.',
            'pause_heading' => '3. Statuts de pause du SLA',
            'pause_intro' => 'L\'onglet Statuts comporte une colonne dédiée « Pause SLA ». Marquez tout statut représentant un ticket bloqué par un élément hors du contrôle de l\'équipe. Les cas classiques sont :',
            'pause_awaiting' => '<strong>En attente de réponse</strong> &mdash; le client nous doit une information. Une pause quasi universellement considérée comme équitable.',
            'pause_vendor' => '<strong>En attente (fournisseur)</strong> &mdash; en attente du support Microsoft ou d\'un tiers.',
            'pause_change' => '<strong>En attente (fenêtre de changement)</strong> &mdash; planifié pour une future fenêtre de maintenance.',
            'pause_parts' => '<strong>En attente (pièces)</strong> &mdash; en attente de la livraison de matériel.',
            'pause_warn' => 'Un statut générique « En attente » peut être détourné comme échappatoire au SLA lorsqu\'un ticket est difficile ou que l\'analyste est occupé. Si votre équipe est disciplinée, cela ne pose pas de problème. Sinon, envisagez de le remplacer par les variantes plus précises ci-dessus, ou appuyez-vous sur le tableau de bord <strong>Watchtower</strong>, qui signale par une alerte orange les tickets en pause depuis plus de 24 heures.',
            'cutoff_heading' => '4. Date d\'entrée en vigueur (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'Le paramètre global le plus important. Tant que vous n\'avez pas défini de date et heure ici, le suivi des SLA est entièrement désactivé &mdash; aucune horloge ne tourne, aucune pastille ne s\'affiche dans la boîte de réception, aucun e-mail de dépassement n\'est envoyé. Définir une date passée active les SLA rétroactivement à partir de ce moment. Définir une date future planifie l\'activation.',
            'cutoff_p2' => 'La plupart des équipes règlent ce paramètre sur « maintenant » lors de la première activation des SLA &mdash; les tickets existants conservent leur état antérieur, et les nouveaux tickets sont suivis à partir de ce moment.',
            'company_heading' => 'Chaque client avec ses propres priorités et horaires',
            'company_p1' => 'Sur une installation qui sert plusieurs entreprises, une priorité ou un calendrier ouvré peut être <strong>partagé</strong> par toutes les entreprises ou appartenir à <strong>une seule entreprise</strong> - choisissez-le dans le champ <strong>Entreprise</strong> lors de l\'ajout. Une entreprise voit ses propres priorités ainsi que les priorités partagées qu\'elle n\'a pas masquées, et démarre les nouveaux tickets sur sa propre valeur par défaut (sinon sur la valeur par défaut partagée). Chaque sélecteur de priorité suit l\'entreprise du ticket, et chaque canal qui ouvre un ticket le démarre sur la valeur par défaut de cette entreprise.',
            'company_p2' => 'Le chronomètre suit le calendrier propre à la priorité ; à défaut, le calendrier par défaut de l\'entreprise ; puis le calendrier partagé par défaut. Une priorité partagée ne peut utiliser que des calendriers partagés. Déplacer un ticket vers une entreprise qui ne peut pas utiliser sa priorité le bascule sur la priorité par défaut de cette entreprise, ce qui est consigné dans l\'historique du ticket.',
            'company_note' => 'Modifier une priorité ou un calendrier <strong>partagé</strong> le modifie pour toutes les entreprises, ce qui exige l\'accès à toutes les entreprises. Ceux d\'une entreprise exigent l\'accès à cette entreprise. Sur une installation à entreprise unique, tout cela est invisible - tout est partagé.',
        ],
        'behaviour' => [
            'heading' => 'Paramètres de comportement',
            'sub' => 'Ils déterminent la réaction du moteur face aux cas particuliers. Les valeurs par défaut sont raisonnables &mdash; vous n\'avez besoin de les modifier qu\'en cas de préférence particulière.',
            'prio_heading' => 'Lorsque la priorité change en cours de traitement',
            'prio_intro' => 'Si un ticket P3 est requalifié en P1 à mi-parcours (parce que le problème s\'avère plus important que prévu), trois comportements raisonnables sont possibles :',
            'prio_forward' => '<strong>Report (par défaut)</strong> &mdash; conserve les minutes ouvrées déjà accumulées et applique simplement le nouvel objectif. Si le ticket avait consommé 2h de son objectif P3 de 8h, il a désormais 2h consommées sur son objectif P1 d\'1h &mdash; ce qui signifie qu\'il est déjà en dépassement. Ce choix est défendable : le ticket ÉTAIT un P1 depuis le début, l\'équipe ne s\'en était simplement pas rendu compte.',
            'prio_recompute' => '<strong>Recalcul</strong> &mdash; réinitialise l\'horloge et applique le nouvel objectif rétroactivement depuis la création du ticket. Un recalcul propre.',
            'prio_reset' => '<strong>Réinitialisation</strong> &mdash; démarre une nouvelle horloge à partir du moment du changement de priorité. Le plus indulgent pour l\'équipe, mais les clients peuvent se sentir lésés si un ticket haute priorité se voit soudain attribuer une nouvelle horloge longue.',
            'reopen_heading' => 'Lorsqu\'un ticket fermé est rouvert',
            'reopen_intro' => 'Si un ticket est rouvert (l\'utilisateur répond après la fermeture) :',
            'reopen_reset' => '<strong>Réinitialisation (par défaut)</strong> &mdash; démarre de nouvelles horloges de réponse et de résolution à partir du moment de la réouverture. La réouverture est traitée comme un ticket effectivement nouveau.',
            'reopen_continue' => '<strong>Poursuite</strong> &mdash; reprend à partir du temps écoulé au moment de la fermeture. Les objectifs de SLA d\'origine continuent de s\'appliquer.',
            'first_heading' => 'Définition de la première réponse',
            'first_intro' => 'Qu\'est-ce qui compte comme « première réponse » &mdash; le moment qui arrête l\'horloge de réponse ?',
            'first_either' => '<strong>N\'importe laquelle (par défaut)</strong> &mdash; la première action de l\'analyste, quelle qu\'elle soit : un e-mail sortant, un changement de statut, une attribution.',
            'first_status' => '<strong>Changement de statut</strong> &mdash; seul un changement de statut par rapport au statut par défaut compte. Plus strict &mdash; l\'analyste doit avoir réellement traité le ticket, pas seulement l\'avoir ouvert.',
            'first_email' => '<strong>E-mail sortant</strong> &mdash; seule une réponse par e-mail au demandeur compte. Le plus strict &mdash; le client doit avoir reçu une réponse de notre part.',
            'warn_heading' => 'Seuil d\'avertissement (pourcentage)',
            'warn_body' => 'Détermine à quel pourcentage de l\'objectif de SLA l\'indicateur passe du vert à l\'orange. La valeur par défaut est 80 % &mdash; ainsi, un objectif de réponse de 60 minutes passe à l\'orange après 48 minutes écoulées. Ce seuil déclenche également les notifications de dépassement de type avertissement.',
        ],
        'breach' => [
            'heading' => 'Notifications de dépassement',
            'sub' => 'Des règles d\'e-mail configurables par département, déclenchées lorsque les SLA approchent du dépassement (avertissement) ou sont effectivement dépassés.',
            'intro' => 'Chaque règle comporte quatre dimensions, toutes indépendantes :',
            'scope_heading' => '1. Portée',
            'scope_body' => 'Soit <strong>Par défaut</strong> (la règle s\'applique aux tickets de tous les départements), soit un <strong>département spécifique</strong>. Résolution : une règle spécifique à un département l\'emporte sur la règle par défaut pour les tickets de ce département. Sans règle par défaut, les départements sans règle spécifique ne reçoivent aucune notification.',
            'trigger_heading' => '2. Déclencheur',
            'trigger_body' => 'Soit <strong>Avertissement</strong> (le ticket a franchi le seuil d\'avertissement &mdash; dépassement potentiel), soit <strong>Dépassement</strong> (le ticket a dépassé son objectif &mdash; dépassement effectif). Chacun constitue une règle distincte, ce qui permet de notifier des personnes différentes pour chacun.',
            'target_heading' => '3. Cible',
            'target_body' => 'Quelle horloge surveiller &mdash; <strong>Réponse</strong>, <strong>Résolution</strong>, ou <strong>Les deux</strong>.',
            'recip_heading' => '4. Destinataires',
            'recip_intro' => 'N\'importe quelle combinaison parmi :',
            'recip_assignee' => '<strong>L\'assigné du ticket</strong> &mdash; l\'analyste qui possède actuellement le ticket. Ignoré si le ticket n\'est pas assigné.',
            'recip_teams' => '<strong>Les membres des équipes du département du ticket</strong> &mdash; tous les analystes de toute équipe liée au département du ticket. Couvre l\'ensemble de la file sans avoir à maintenir une liste de diffusion.',
            'recip_specific' => '<strong>Un analyste spécifique</strong> &mdash; le principe du « référent SLA » / « responsable de service », où il s\'agit d\'une personne nommée et non d\'un rôle.',
            'recip_custom' => '<strong>Adresses e-mail personnalisées</strong> &mdash; texte libre séparé par des virgules. Utile pour les boîtes de réception partagées (<code>sla-alerts@company.com</code>), les passerelles e-mail Slack/Teams, ou les listes de diffusion.',
            'tip' => 'Chaque ticket déclenche au maximum un e-mail par couple (cible, déclencheur) &mdash; le worker cron enregistre ce qui a été envoyé dans la table <code>sla_notifications_sent</code>. Un avertissement est donc envoyé une fois, un dépassement une fois, et c\'est tout &mdash; pas de boucle de spam.',
            'warn' => '<strong>Pas de règle = pas d\'e-mail.</strong> Même si tous les tickets du système sont en dépassement, rien ne se déclenche tant que vous n\'avez pas ajouté au moins une règle. Commencez par une paire Avertissement + Dépassement à portée Par défaut pour couvrir l\'ensemble.',
        ],
        'cron' => [
            'heading' => 'Configuration de la tâche cron',
            'sub' => 'Le script de vérification des dépassements doit s\'exécuter selon une planification. Toutes les 5 minutes est la fréquence idéale.',
            'p1' => 'Les indicateurs de SLA visibles dans l\'interface (pastilles dans la boîte de réception, panneaux dans le volet de lecture) sont calculés à la volée au chargement de la page. Mais les e-mails de dépassement ne peuvent partir que si <em>quelque chose</em> vérifie les tickets de façon proactive, même quand personne ne les regarde. Ce quelque chose est une tâche planifiée &mdash; sous Windows, le Planificateur de tâches ; sous Linux, cron.',
            'p2' => 'Le script est <code>cron/sla_breach_check.php</code>, dans le répertoire d\'installation de FreeITSM. Il peut être appelé de deux façons :',
            'cli_heading' => 'A. CLI (recommandé sur un serveur que vous contrôlez)',
            'cli_note' => 'Aucune authentification requise &mdash; les permissions du système de fichiers déterminent déjà qui peut l\'exécuter.',
            'http_heading' => 'B. HTTP (pour un hébergement mutualisé ou des planificateurs distants)',
            'http_note' => 'Le jeton est généré automatiquement lors de la première installation et stocké dans <code>system_settings</code> sous la clé <code>sla_cron_token</code> (32 caractères hexadécimaux, ~128 bits d\'entropie). Il est chiffré au repos, donc lire la ligne directement vous donne <code>ENC:…</code> plutôt que le jeton. Trouvez le vôtre avec :',
            'win_heading' => 'Planificateur de tâches Windows',
            'win_intro' => 'Ouvrez le Planificateur de tâches (<code>taskschd.msc</code>) et créez une nouvelle tâche avec ces paramètres :',
            'tbl_field' => 'Champ',
            'tbl_value' => 'Valeur',
            'win_r1_k' => 'Nom',
            'win_r1_v' => 'FreeITSM &mdash; Vérification des dépassements de SLA',
            'win_r2_k' => 'Exécuter que l\'utilisateur soit connecté ou non',
            'win_r2_v' => 'Cochez cette case',
            'win_r3_k' => 'Déclencheur',
            'win_r3_v' => 'Quotidien, récurrence tous les 1 jour, répéter toutes les 5 minutes pendant 1 jour',
            'win_r4_k' => 'Action',
            'win_r4_v' => 'Démarrer un programme',
            'win_r5_k' => 'Programme/script',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Ajouter des arguments',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Démarrer dans',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron Linux',
            'linux_intro' => 'Ajoutez une ligne à votre crontab (<code>crontab -e</code>) :',
            'sec_heading' => 'Sécurité &mdash; ce qui protège le point de terminaison HTTP',
            'sec_intro' => 'Trois niveaux de protection, tous appliqués automatiquement :',
            'sec_token' => '<strong>1. Jeton secret partagé</strong> &mdash; aléatoire de 128 bits par installation, comparé avec une correspondance en temps constant pour empêcher les attaques temporelles.',
            'sec_lockout' => '<strong>2. Blocage par IP après échecs d\'authentification</strong> &mdash; plus de 10 tentatives avec un jeton erroné depuis la même IP au cours de la dernière heure déclenchent un blocage 429 d\'une heure. Contre les tentatives de force brute sans avoir besoin de fail2ban.',
            'sec_interval' => '<strong>3. Intervalle minimal entre deux exécutions réussies</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (30 s par défaut). Même une requête avec un jeton valide reçoit un 429 si elle arrive avant ce délai depuis la dernière exécution réussie. Empêche les doubles planifications accidentelles et les boucles incontrôlées.',
            'log_heading' => 'Journal d\'activité',
            'log_body' => 'Chaque appel (accepté ou rejeté) est consigné dans la table <code>sla_cron_runs</code> avec l\'horodatage, le résultat, les compteurs et l\'IP du client. Consultez les 20 dernières exécutions dans le panneau <strong>Activité Cron</strong> en bas de l\'onglet des paramètres SLA &mdash; utile pour vérifier que la planification se déclenche bien et pour auditer les tentatives d\'authentification échouées. Les lignes sont purgées automatiquement après <code>sla_cron_log_retention_days</code> (30 par défaut) afin que la table reste de taille raisonnable.',
        ],
        'examples' => [
            'heading' => 'Exemples détaillés',
            'sub' => 'Du cas simple avec un seul fuseau horaire au cas plus délicat multi-fuseaux, où la notion d\'« équité » doit être définie.',
            'ex1_heading' => 'Exemple 1 : ticket créé au Royaume-Uni, centre de support au Royaume-Uni',
            'ex1_title' => 'Le cas simple',
            'ex1_tag' => 'fuseau horaire unique',
            'ex1_setup' => '<strong>Configuration :</strong> un calendrier d\'heures ouvrées appelé <em>UK Office</em> avec le fuseau horaire <code>Europe/London</code>, du lundi au vendredi 09:00-17:00, aucun jour férié. La priorité P2 a un objectif de réponse de 1 heure et un objectif de résolution de 4 heures, tous deux calculés sur le calendrier <em>UK Office</em>.',
            'ex1_scenario' => '<strong>Scénario :</strong> un utilisateur crée un ticket P2 à <strong>16h30 (Royaume-Uni), un mercredi</strong>.',
            'ex1_timeline' => 'Mer 16h30 (RU) &mdash; <strong>ticket créé</strong>, le chronomètre de réponse démarre.
Mer 17h00 (RU) &mdash; fermeture du bureau, le chronomètre se met en pause (30 min consommées sur 60 min d\'objectif).
Jeu 09h00 (RU) &mdash; ouverture du bureau, le chronomètre reprend.
Jeu 09h30 (RU) &mdash; l\'analyste répond. Objectif de réponse atteint tout juste à temps (60 min consommées, 60 min d\'objectif).',
            'ex1_outro' => 'Si l\'analyste n\'avait répondu qu\'à <strong>10h00 (RU) le jeudi</strong>, la réponse aurait <strong>dépassé son objectif de 30 minutes</strong> (90 min consommées contre 60 min d\'objectif &mdash; 30 depuis mercredi soir, 60 depuis jeudi matin). Le chronomètre d\'une heure ne tourne que pendant les heures ouvrées, mais un ticket créé en fin de journée consomme malgré tout la majeure partie de son budget dès la réouverture du bureau &mdash; un analyste qui arrive à 09h00 peut facilement croire qu\'il dispose de l\'heure complète, alors qu\'il ne reste en réalité que 30 minutes.',
            'ex2_heading' => 'Exemple 2 : ticket créé au Royaume-Uni, centre de support en Estonie',
            'ex2_title' => 'Le cas multi-fuseaux',
            'ex2_tag' => '3 façons de définir l\'« équité »',
            'ex2_setup' => '<strong>Configuration :</strong> clients au Royaume-Uni (<code>Europe/London</code>, GMT/BST), centre de support en Estonie (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 heures d\'avance sur le Royaume-Uni</strong>). Les deux équipes travaillent nominalement de 09h00 à 17h00, heure locale.',
            'ex2_scenario' => '<strong>Scénario :</strong> un client britannique crée un ticket P2 à <strong>16h30 (RU) un vendredi</strong> (= 18h30 en Estonie, après la fermeture du bureau estonien). La première occasion pour un analyste estonien de le traiter est le lundi à 09h00 (Estonie) (= 07h00 RU). L\'objectif de réponse est de 1 heure.',
            'ex2_question' => 'Que doit dire le SLA ? Il existe trois réponses défendables, chacune équitable dans un sens différent. C\'est vous qui choisissez quel calendrier attribuer à la priorité, en fonction de ce que promet votre contrat de service.',
            'optA_label' => 'Option A &mdash; centrée sur le client',
            'optA_p1' => '<strong>Configurez la priorité pour utiliser un calendrier aux horaires du <em>Royaume-Uni</em>.</strong> Le chronomètre tourne sur la plage 09h00-17h00 RU, quel que soit l\'endroit où se trouve l\'analyste.',
            'optA_p2' => 'Dans le scénario ci-dessus, ticket créé à 16h30 RU le vendredi : le chronomètre tourne de 16h30 à 17h00 RU le vendredi (30 min consommées), se met en pause pour la nuit et le week-end, puis reprend lundi à 09h00 RU. Si un analyste estonien répond à 10h00 (Estonie) le lundi (= 08h00 RU), le calendrier RU est encore en pause (le bureau RU ouvre à 09h00 RU), donc aucune minute supplémentaire n\'est comptée &mdash; la consommation reste à 30 min. <strong>SLA respecté avec 30 min de marge</strong>. Toute réponse après 09h30 RU (= 11h30 Estonie) entraînerait un dépassement.',
            'optA_p3' => '<em>Équitable pour :</em> le client. Son expérience correspond à sa propre journée de travail.<br><em>Contrepartie :</em> les analystes estoniens doivent être disponibles de 09h00 à 17h00 heure RU (= 11h00-19h00 en Estonie), ce qui allonge leur journée de travail de 2 heures.',
            'optB_label' => 'Option B &mdash; centrée sur l\'analyste',
            'optB_p1' => '<strong>Configurez la priorité pour utiliser un calendrier aux horaires de l\'<em>Estonie</em>.</strong> Le chronomètre tourne sur la plage 09h00-17h00 (Estonie).',
            'optB_p2' => 'Même scénario : ticket créé à 18h30 (Estonie) le vendredi (après fermeture), le chronomètre reste en pause tout le week-end et démarre lundi à 09h00 (Estonie) (= 07h00 RU). Si l\'analyste répond à 09h30 (Estonie) le lundi (= 07h30 RU), le SLA de réponse a consommé 30 min sur les 60 min d\'objectif &mdash; <strong>respecté avec 30 min de marge</strong>. Le client britannique a créé son ticket à 16h30 RU le vendredi et a reçu une réponse à 07h30 RU le lundi &mdash; son attente réelle a été bien plus longue que ne le laisse penser le SLA.',
            'optB_p3' => '<em>Équitable pour :</em> les analystes. Ils travaillent à leurs horaires normaux.<br><em>Contrepartie :</em> les clients britanniques peuvent avoir l\'impression que le SLA « ment » si un ticket du vendredi après-midi n\'est pris en compte que le lundi matin heure estonienne, alors que le rapport indique un SLA de réponse d\'une heure. Assurez-vous que votre contrat de service précise explicitement que le SLA se calcule sur les heures du centre de support.',
            'optC_label' => 'Option C &mdash; fenêtre de chevauchement (la plus stricte)',
            'optC_p1' => '<strong>Configurez la priorité pour utiliser un calendrier ne couvrant que les heures où les deux centres sont ouverts.</strong> Les horaires 09h00-17h00 RU chevauchent les horaires 09h00-17h00 Estonie (= 07h00-15h00 RU) sur la <strong>plage 09h00-15h00 RU</strong> &mdash; soit 6 heures par jour ouvré.',
            'optC_p2' => 'Même scénario : ticket créé à 16h30 RU le vendredi (en dehors du chevauchement, qui se termine à 15h00 RU), le chronomètre reste en pause pendant le week-end et reprend lundi à 09h00 RU (= 11h00 Estonie, le moment où le chevauchement rouvre). Si l\'analyste estonien répond à 11h30 (Estonie) (= 09h30 RU), le SLA de réponse a consommé 30 min sur les 60 min d\'objectif &mdash; <strong>respecté avec 30 min de marge</strong>. La réponse a eu lieu pendant la fenêtre de chevauchement, elle compte donc immédiatement.',
            'optC_p3' => '<em>Équitable pour :</em> les deux parties &mdash; le SLA ne tourne que pendant les heures où le centre de support peut réellement avancer sur le ticket ET où le client est présent pour recevoir une réponse.<br><em>Contrepartie :</em> une fenêtre quotidienne plus courte signifie des délais réels plus longs pour atteindre des objectifs ambitieux. Un objectif de résolution de 4 heures s\'étale sur 1,5 jour de chevauchement, alors qu\'avec un calendrier normal de 8 heures il serait tenu en une seule journée.',
            'choose_tip' => '<strong>Comment choisir :</strong> examinez votre contrat de service. S\'il dit « réponse dans l\'heure suivant la réception » &mdash; c\'est l\'option A (horloge du client). S\'il dit « réponse dans l\'heure ouvrée » &mdash; c\'est en général l\'option B (le centre en poste, quel qu\'il soit). S\'il dit « dans l\'heure suivant la disponibilité mutuelle » &mdash; c\'est l\'option C. En l\'absence de contrat, posez la question à l\'équipe : voulez-vous ressentir une pression en dehors des heures estoniennes (option A), ou accepter que les clients britanniques se sentent parfois ignorés (option B) ?',
            'ex3_heading' => 'Exemple 3 : mise en pause du chronomètre en attente d\'un fournisseur',
            'ex3_title' => 'Comment fonctionnent les statuts de pause en pratique',
            'ex3_tag' => 'pause du chronomètre',
            'ex3_setup' => '<strong>Configuration :</strong> priorité P3 avec un objectif de résolution de 8 heures ouvrées, calendrier RU, statut « En attente du fournisseur » marqué <em>Pause SLA</em>.',
            'ex3_scenario' => '<strong>Scénario :</strong> ticket créé le lundi à 09h00 RU. L\'analyste escalade auprès de Microsoft le lundi à 11h00 RU et passe le ticket en « En attente du fournisseur ». Microsoft répond le mercredi à 14h00 RU. L\'analyste applique le correctif et ferme le ticket le jeudi à 10h00 RU.',
            'ex3_timeline' => 'Lun 09h00 &mdash; ticket créé, le chronomètre de résolution tourne.
Lun 11h00 &mdash; passage en « En attente du fournisseur », <strong>chronomètre en pause</strong> (2h consommées).
Mer 14h00 &mdash; retour en « En cours », <strong>le chronomètre reprend</strong>.
Mer 17h00 &mdash; fermeture du bureau (5h consommées au total).
Jeu 09h00 &mdash; ouverture du bureau.
Jeu 10h00 &mdash; ticket fermé (6h consommées au total). <strong>SLA respecté</strong> contre un objectif de 8h.',
            'ex3_outro' => 'Temps réel écoulé : ~3 jours. Temps SLA écoulé : 6 heures ouvrées. Sans le marquage du statut de pause, le SLA aurait compté les 2 jours d\'attente du fournisseur en plus des heures ouvrées, soit environ 18 heures ouvrées au total &mdash; largement au-delà du dépassement.',
        ],
