            'r1_c' => '<code>Enforce SLAs from</code> est vide, la priorité n\'a aucun objectif défini, ou le ticket est antérieur à la date de bascule.',
            'r2_s' => 'Le SLA indique un dépassement alors que l\'analyste a répondu dans les délais',
            'r2_c' => 'Consultez l\'historique des changements de priorité &mdash; si la priorité a été relevée en cours de traitement et que le comportement est réglé sur « Forward » (par défaut), le temps déjà accumulé est reporté.',
            'r3_s' => 'Les notifications de dépassement ne partent pas',
