            'r5_c' => 'Ces tickets sont dans un statut qui met le SLA en pause. Soit quelqu\'un les a délibérément mis de côté et a oublié, soit quelqu\'un utilise « On Hold » comme échappatoire au SLA. Ouvrez chaque ticket et faites-le avancer, ou retirez le statut de pause.',
            'r6_s' => 'Le cron HTTP renvoie 403',
