            'r7_s' => 'Le cron HTTP renvoie 429 « Rate limited »',
            'r7_c' => 'Une exécution réussie s\'est terminée il y a moins de <code>sla_cron_min_interval_seconds</code> (30 s par défaut). Attendez, ou réduisez ce paramètre.',
            'r8_s' => 'Le cron HTTP renvoie 429 « Too many failed attempts »',
            'r8_c' => 'Cette IP a dépassé 10 tentatives avec un jeton erroné au cours de la dernière heure. Attendez 1 heure, ou effacez les échecs : <code>DELETE FROM sla_cron_runs WHERE client_ip = \'...\' AND outcome = \'auth_failed\'</code>.',
            'tip' => 'Pour une présentation technique détaillée de la configuration du cron, incluant des exemples Linux et l\'intégration avec un planificateur distant, consultez <code>docs/sla-cron-setup.md</code> dans le répertoire d\'installation de FreeITSM.',
